// Union européenne (2) : histoire de la construction européenne (pères fondateurs, CECA, CED, traités de Rome à Lisbonne, TSCG),
// élargissements et retraits, candidats, États membres, euro et Schengen, institutions (art. 13 TUE), organes, agences et leurs sièges,
// processus décisionnels, rôle des parlements nationaux (art. 88-1 à 88-7 de la Constitution), symboles et citoyenneté.
BANK.push(
// --- Avant les traités : idées et premières organisations ---
{id:"ue2-001",t:"ue",q:"En septembre 1946, à Zurich, quel homme d'État appelle à bâtir « une sorte d'États-Unis d'Europe » ?",o:["Robert Schuman","Charles de Gaulle","Konrad Adenauer","Winston Churchill"],a:3,e:"Discours de l'université de Zurich du 19 septembre 1946, fondé sur la réconciliation franco-allemande.",s:"Banque UE"},
{id:"ue2-002",t:"ue",q:"Quel congrès de mai 1948, placé sous la présidence d'honneur de Winston Churchill, a donné l'impulsion à la création du Conseil de l'Europe ?",o:["Le congrès de La Haye","La conférence de Messine","La conférence de Yalta","Le congrès de Vienne"],a:0,e:"Le « congrès de l'Europe » réunit à La Haye du 7 au 10 mai 1948 les mouvements européens ; il aboutit au Conseil de l'Europe (1949).",u:["https://fr.wikipedia.org/wiki/Congr%C3%A8s_de_La_Haye"],s:"Banque UE"},
{id:"ue2-003",t:"ue",q:"Par quel texte le Conseil de l'Europe a-t-il été créé le 5 mai 1949 ?",o:["Le traité de Paris","Le traité de Rome","Le traité de Bruxelles","Le traité de Londres"],a:3,e:"Signé à Londres par dix États ; le Conseil de l'Europe siège à Strasbourg.",u:["https://fr.wikipedia.org/wiki/Statut_du_Conseil_de_l%27Europe"],s:"Banque UE"},
{id:"ue2-004",t:"ue",q:"Quelle fonction Robert Schuman occupe-t-il lorsqu'il prononce sa déclaration du 9 mai 1950 ?",o:["Ministre des Affaires étrangères","Président du Conseil","Président de la République","Commissaire général au Plan"],a:0,e:"Le texte a été préparé par Jean Monnet, alors commissaire général au Plan.",u:["https://fr.wikipedia.org/wiki/Robert_Schuman"],s:"Banque UE"},
{id:"ue2-005",t:"ue",q:"Qui a été le premier président de la Haute Autorité de la CECA ?",o:["Robert Schuman","Paul-Henri Spaak","Walter Hallstein","Jean Monnet"],a:3,e:"Jean Monnet la préside de 1952 à 1955, puis fonde le Comité d'action pour les États-Unis d'Europe.",u:["https://fr.wikipedia.org/wiki/Jean_Monnet"],s:"Banque UE"},
// --- CECA, CED et traités de Rome ---
{id:"ue2-006",t:"ue",q:"Pour quelle durée le traité instituant la CECA avait-il été conclu ?",o:["10 ans","25 ans","50 ans","Une durée illimitée"],a:2,e:"Entré en vigueur le 23 juillet 1952, il a expiré le 23 juillet 2002 ; ses activités ont été reprises par la Communauté européenne.",u:["https://fr.wikipedia.org/wiki/Communaut%C3%A9_europ%C3%A9enne_du_charbon_et_de_l%27acier"],s:"Banque UE"},
{id:"ue2-007",t:"ue",q:"De quel plan, présenté en octobre 1950, est issue la Communauté européenne de défense (CED) ?",o:["Le plan Pleven","Le plan Fouchet","Le plan Werner","Le plan Marshall"],a:0,e:"René Pleven, président du Conseil, propose une armée européenne intégrée ; le traité CED est signé le 27 mai 1952.",u:["https://fr.wikipedia.org/wiki/Plan_Pleven"],s:"Banque UE"},
{id:"ue2-008",t:"ue",q:"Quelle assemblée a fait échouer la Communauté européenne de défense le 30 août 1954 ?",o:["L'Assemblée nationale française","Le Bundestag allemand","Le Parlement italien","La Chambre des communes britannique"],a:0,e:"Elle a adopté une question préalable qui a rejeté le traité sans débat.",u:["https://fr.wikipedia.org/wiki/Communaut%C3%A9_europ%C3%A9enne_de_d%C3%A9fense"],s:"Banque UE"},
{id:"ue2-009",t:"ue",q:"Quelle conférence de juin 1955 a relancé la construction européenne après l'échec de la CED ?",o:["La conférence de La Haye","Le Conseil européen de Fontainebleau","La conférence de Stresa","La conférence de Messine"],a:3,e:"Les ministres des Six y confient à Paul-Henri Spaak la préparation du marché commun et de la communauté atomique.",u:["https://fr.wikipedia.org/wiki/Conf%C3%A9rence_de_Messine"],s:"Banque UE"},
{id:"ue2-010",t:"ue",q:"Quel homme d'État belge a présidé le comité dont le rapport de 1956 a préparé les traités de Rome ?",o:["Joseph Bech","Leo Tindemans","Johan Willem Beyen","Paul-Henri Spaak"],a:3,e:"Le rapport Spaak, approuvé à Venise en mai 1956, sert de base aux négociations des traités CEE et Euratom.",u:["https://fr.wikipedia.org/wiki/Paul-Henri_Spaak"],s:"Banque UE"},
{id:"ue2-011",t:"ue",q:"Dans quel lieu de Rome les traités du 25 mars 1957 ont-ils été signés ?",o:["Au Capitole","Au Vatican","Au palais du Quirinal","Au palais Chigi"],a:0,e:"Dans la salle des Horaces et des Curiaces du palais des Conservateurs, sur la colline du Capitole.",u:["https://fr.wikipedia.org/wiki/Trait%C3%A9_instituant_la_Communaut%C3%A9_%C3%A9conomique_europ%C3%A9enne"],s:"Banque UE"},
{id:"ue2-012",t:"ue",q:"Quand les traités de Rome sont-ils entrés en vigueur ?",o:["25 mars 1957","1er janvier 1958","1er juillet 1968","1er janvier 1973"],a:1,e:"Signés le 25 mars 1957, ils entrent en vigueur le 1er janvier 1958.",u:["https://fr.wikipedia.org/wiki/Trait%C3%A9_instituant_la_Communaut%C3%A9_%C3%A9conomique_europ%C3%A9enne"],s:"Banque UE"},
{id:"ue2-013",t:"ue",q:"Quel organe consultatif a été créé par les traités de Rome de 1957 ?",o:["Le Comité des régions","Le Médiateur européen","La Cour des comptes","Le Comité économique et social"],a:3,e:"Le Comité des régions et le Médiateur datent de Maastricht, la Cour des comptes de 1975.",u:["https://fr.wikipedia.org/wiki/Comit%C3%A9_%C3%A9conomique_et_social_europ%C3%A9en"],s:"Banque UE"},
{id:"ue2-014",t:"ue",q:"Laquelle de ces Communautés existe encore aujourd'hui en tant que telle, à côté de l'Union européenne ?",o:["Euratom","La CECA","La CEE","La CED"],a:0,e:"La CECA a expiré en 2002, la CEE est devenue la CE puis a été absorbée par l'Union (Lisbonne), la CED n'a jamais vu le jour.",u:["https://fr.wikipedia.org/wiki/Communaut%C3%A9_europ%C3%A9enne_de_l%27%C3%A9nergie_atomique"],s:"Banque UE"},
{id:"ue2-015",t:"ue",q:"Quel traité de 1965, entré en vigueur en 1967, a institué une Commission unique et un Conseil unique pour les trois Communautés ?",o:["L'Acte unique européen","Le traité de Rome","Le traité de Maastricht","Le traité de fusion des exécutifs"],a:3,e:"Signé à Bruxelles le 8 avril 1965, il prend effet le 1er juillet 1967.",u:["https://fr.wikipedia.org/wiki/Trait%C3%A9_de_fusion"],s:"Banque UE"},
{id:"ue2-016",t:"ue",q:"Qui a été le premier président de la Commission de la CEE (1958-1967) ?",o:["Walter Hallstein","Jean Monnet","Jacques Delors","Sicco Mansholt"],a:0,e:"Juriste allemand, proche d'Adenauer ; Sicco Mansholt fut commissaire à l'agriculture puis président en 1972.",u:["https://fr.wikipedia.org/wiki/Walter_Hallstein"],s:"Banque UE"},
// --- Années 1960 à 1985 ---
{id:"ue2-017",t:"ue",q:"Quel était l'objet des plans Fouchet (1961-1962) ?",o:["Une monnaie unique","Une armée européenne intégrée","L'élection du Parlement européen au suffrage universel","Une union politique des États, de nature intergouvernementale"],a:3,e:"Inspirés par le général de Gaulle, ils échouent en 1962 face à l'opposition de la Belgique et des Pays-Bas.",u:["https://fr.wikipedia.org/wiki/Plan_Fouchet"],s:"Banque UE"},
{id:"ue2-018",t:"ue",q:"Qu'appelle-t-on la « politique de la chaise vide » (1965-1966) ?",o:["Le boycott des réunions du Conseil par la France","Le refus britannique de siéger au Parlement européen","La vacance de la présidence de la Commission","Le boycott de la CECA par l'Allemagne"],a:0,e:"La France s'oppose aux propositions de la Commission Hallstein sur le financement de la PAC et au passage prévu à la majorité qualifiée.",u:["https://fr.wikipedia.org/wiki/Crise_de_la_chaise_vide"],s:"Banque UE"},
{id:"ue2-019",t:"ue",q:"Que prévoit le compromis de Luxembourg de janvier 1966 ?",o:["Quand un État invoque des intérêts très importants, le Conseil s'efforce de trouver une solution acceptable par tous","Le passage à la majorité qualifiée pour toutes les décisions du Conseil","Le transfert à la Commission du pouvoir de trancher en cas de blocage au Conseil","L'abandon de la PAC au profit d'aides agricoles nationales"],a:0,e:"Il met fin à la crise de la chaise vide et instaure, en pratique, un droit de veto.",u:["https://fr.wikipedia.org/wiki/Compromis_de_Luxembourg"],s:"Banque UE"},
{id:"ue2-020",t:"ue",q:"Combien de fois le général de Gaulle s'est-il opposé à l'entrée du Royaume-Uni dans la CEE ?",o:["Une fois","Deux fois","Trois fois","Jamais"],a:1,e:"En 1963 et en 1967. Le Royaume-Uni adhère en 1973, sous la présidence de Georges Pompidou.",s:"Banque UE"},
{id:"ue2-021",t:"ue",q:"Quel sommet de décembre 1969 a fixé le triptyque « achèvement, approfondissement, élargissement » ?",o:["Le sommet de Paris","Le Conseil européen de Fontainebleau","Le Conseil européen de Copenhague","Le sommet de La Haye"],a:3,e:"Il ouvre la voie au premier élargissement et au projet d'union économique et monétaire.",s:"Banque UE"},
{id:"ue2-022",t:"ue",q:"Quel rapport de 1970 propose pour la première fois une union économique et monétaire réalisée par étapes ?",o:["Le rapport Delors","Le rapport Tindemans","Le plan Fouchet","Le plan Werner"],a:3,e:"Du nom du Premier ministre luxembourgeois Pierre Werner. Le rapport Delors de 1989 relance ce projet en trois étapes.",u:["https://fr.wikipedia.org/wiki/Rapport_Werner"],s:"Banque UE"},
{id:"ue2-023",t:"ue",q:"Depuis quel traité le Conseil européen est-il une institution de l'Union ?",o:["Le traité de Lisbonne","L'Acte unique européen","Le traité de Maastricht","Le traité de Nice"],a:0,e:"L'Acte unique et Maastricht le mentionnaient, mais il n'est institution (art. 13 TUE) que depuis le 1er décembre 2009.",u:["https://fr.wikipedia.org/wiki/Conseil_europ%C3%A9en"],s:"TUE, art. 13"},
{id:"ue2-024",t:"ue",q:"Quel dispositif de stabilité des changes a été lancé en 1979, avec l'écu comme unité de compte ?",o:["Le Système monétaire européen (SME)","Le serpent monétaire européen","Le Mécanisme européen de stabilité","L'union bancaire"],a:0,e:"Le SME (mars 1979) succède au « serpent » de 1972 ; l'euro remplace l'écu au taux de 1 pour 1 le 1er janvier 1999.",u:["https://fr.wikipedia.org/wiki/Syst%C3%A8me_mon%C3%A9taire_europ%C3%A9en"],s:"Banque UE"},
{id:"ue2-025",t:"ue",q:"Qui a été élue en 1979 première présidente du Parlement européen élu au suffrage universel direct ?",o:["Nicole Fontaine","Louise Weiss","Roberta Metsola","Simone Veil"],a:3,e:"Simone Veil préside le Parlement de 1979 à 1982 ; Louise Weiss avait ouvert la session en tant que doyenne d'âge.",u:["https://fr.wikipedia.org/wiki/Simone_Veil"],s:"Banque UE"},
{id:"ue2-026",t:"ue",q:"Quel Français a présidé la Commission européenne de 1985 à 1995 ?",o:["François-Xavier Ortoli","Michel Barnier","Valéry Giscard d'Estaing","Jacques Delors"],a:3,e:"Trois mandats marqués par l'Acte unique, le marché intérieur et la préparation de l'union monétaire.",u:["https://fr.wikipedia.org/wiki/Jacques_Delors"],s:"Banque UE"},
// --- Schengen ---
{id:"ue2-027",t:"ue",q:"Où les accords de Schengen ont-ils été signés le 14 juin 1985 ?",o:["Au Luxembourg, à bord d'un bateau sur la Moselle","En Belgique, au siège de la Commission","En France, à Strasbourg","Aux Pays-Bas, à Maastricht"],a:0,e:"À bord du Princesse Marie-Astrid, près du village luxembourgeois de Schengen, à la frontière de la France et de l'Allemagne.",u:["https://fr.wikipedia.org/wiki/Accord_de_Schengen"],s:"Banque UE"},
{id:"ue2-028",t:"ue",q:"Combien d'États ont signé l'accord de Schengen en 1985 ?",o:["3","5","6","12"],a:1,e:"France, RFA, Belgique, Pays-Bas et Luxembourg.",u:["https://fr.wikipedia.org/wiki/Accord_de_Schengen"],s:"Banque UE"},
{id:"ue2-029",t:"ue",q:"Quel traité a intégré l'acquis de Schengen dans le cadre de l'Union européenne ?",o:["Le traité d'Amsterdam","Le traité de Maastricht","Le traité de Nice","Le traité de Lisbonne"],a:0,e:"Par un protocole annexé, en vigueur depuis le 1er mai 1999.",u:["https://fr.wikipedia.org/wiki/Trait%C3%A9_d%27Amsterdam"],s:"Banque UE"},
{id:"ue2-030",t:"ue",q:"Lequel de ces pays, non membre de l'Union européenne, fait partie de l'espace Schengen ?",o:["Le Royaume-Uni","La Serbie","La Turquie","La Suisse"],a:3,e:"Quatre États non membres y participent : Islande, Norvège, Suisse et Liechtenstein.",u:["https://fr.wikipedia.org/wiki/Espace_Schengen"],s:"Banque UE"},
{id:"ue2-031",t:"ue",q:"Quel État membre de l'UE bénéficie d'une exemption et ne participe pas à l'espace Schengen ?",o:["Le Danemark","La Bulgarie","La Croatie","L'Irlande"],a:3,e:"L'Irlande partage avec le Royaume-Uni une zone de libre circulation (Common Travel Area). Le Danemark applique Schengen.",u:["https://fr.wikipedia.org/wiki/Espace_Schengen"],s:"Banque UE"},
{id:"ue2-032",t:"ue",q:"En 2023, la Croatie a rejoint à la fois :",o:["La zone euro et l'espace Schengen","L'Union européenne et l'OTAN","La zone euro et l'OTAN","L'espace Schengen et l'AELE"],a:0,e:"Le 1er janvier 2023. Elle était membre de l'OTAN depuis 2009 et de l'UE depuis le 1er juillet 2013.",u:["https://fr.wikipedia.org/wiki/Adh%C3%A9sion_de_la_Croatie_%C3%A0_l%27Union_europ%C3%A9enne"],s:"Banque UE"},
// --- Acte unique et traité de Maastricht ---
{id:"ue2-033",t:"ue",q:"Dans quelles villes l'Acte unique européen a-t-il été signé en février 1986 ?",o:["Luxembourg et La Haye","Rome et Paris","Bruxelles et Strasbourg","Maastricht et Amsterdam"],a:0,e:"Neuf États signent à Luxembourg le 17 février, le Danemark, l'Italie et la Grèce à La Haye le 28 février.",u:["https://fr.wikipedia.org/wiki/Acte_unique_europ%C3%A9en"],s:"Banque UE"},
{id:"ue2-034",t:"ue",q:"Quand l'Acte unique européen est-il entré en vigueur ?",o:["1er janvier 1986","1er juillet 1987","1er janvier 1993","1er novembre 1993"],a:1,e:"Il fixe l'achèvement du marché intérieur au 31 décembre 1992.",u:["https://fr.wikipedia.org/wiki/Acte_unique_europ%C3%A9en"],s:"Banque UE"},
{id:"ue2-035",t:"ue",q:"Quelle procédure de décision l'Acte unique européen a-t-il introduite ?",o:["La codécision","La procédure législative ordinaire","L'initiative citoyenne européenne","La procédure de coopération avec le Parlement européen"],a:3,e:"Il crée aussi l'avis conforme et étend la majorité qualifiée. La codécision vient de Maastricht, la procédure législative ordinaire de Lisbonne.",u:["https://fr.wikipedia.org/wiki/Acte_unique_europ%C3%A9en"],s:"Banque UE"},
{id:"ue2-036",t:"ue",q:"Quand le traité de Maastricht est-il entré en vigueur ?",o:["7 février 1992","1er janvier 1993","1er novembre 1993","1er janvier 1999"],a:2,e:"Signé le 7 février 1992, il a été retardé par le « non » danois et la procédure allemande de ratification.",u:["https://fr.wikipedia.org/wiki/Trait%C3%A9_de_Maastricht"],s:"Banque UE"},
{id:"ue2-037",t:"ue",q:"Quels étaient les trois piliers de l'Union européenne créés par le traité de Maastricht ?",o:["Le Parlement, le Conseil et la Commission","L'euro, Schengen et la PAC","Le marché intérieur, la cohésion et la recherche","Les Communautés européennes, la PESC, la justice et les affaires intérieures"],a:3,e:"Le premier pilier est communautaire, les deux autres intergouvernementaux.",u:["https://fr.wikipedia.org/wiki/Piliers_de_l%27Union_europ%C3%A9enne"],s:"Banque UE"},
{id:"ue2-038",t:"ue",q:"Quel traité a supprimé la structure en piliers de l'Union européenne ?",o:["Le traité de Lisbonne","Le traité d'Amsterdam","Le traité de Nice","Le TSCG"],a:0,e:"Lisbonne fusionne les piliers et dote l'Union de la personnalité juridique.",u:["https://fr.wikipedia.org/wiki/Piliers_de_l%27Union_europ%C3%A9enne"],s:"Banque UE"},
{id:"ue2-039",t:"ue",q:"Quel a été le résultat du référendum français du 20 septembre 1992 sur le traité de Maastricht ?",o:["Oui à 51,04 %","Non à 54,67 %","Oui à 68,32 %","Non à 50,70 %"],a:0,e:"Un « petit oui ». 54,67 % de non est le résultat de 2005, 68,32 % de oui celui de 1972 sur l'élargissement.",u:["https://fr.wikipedia.org/wiki/R%C3%A9f%C3%A9rendum_fran%C3%A7ais_sur_le_trait%C3%A9_de_Maastricht"],s:"Banque UE"},
{id:"ue2-040",t:"ue",q:"Quel pays a d'abord rejeté le traité de Maastricht par référendum en juin 1992, avant de l'approuver en 1993 ?",o:["L'Irlande","La France","Le Royaume-Uni","Le Danemark"],a:3,e:"Après l'accord d'Édimbourg lui accordant des dérogations (dont l'euro), le Danemark approuve le traité en mai 1993.",u:["https://fr.wikipedia.org/wiki/Trait%C3%A9_de_Maastricht"],s:"Banque UE"},
{id:"ue2-041",t:"ue",q:"Lequel de ces organes a été créé par le traité de Maastricht ?",o:["Le Comité des régions","Le Comité économique et social","La Cour des comptes européenne","Le Tribunal de première instance"],a:0,e:"Maastricht crée aussi le Médiateur européen. Le CESE date de 1957, la Cour des comptes de 1975, le Tribunal de 1988.",u:["https://fr.wikipedia.org/wiki/Trait%C3%A9_de_Maastricht"],s:"Banque UE"},
{id:"ue2-042",t:"ue",q:"Quel traité a introduit la procédure de codécision entre le Parlement européen et le Conseil ?",o:["L'Acte unique européen","Le traité d'Amsterdam","Le traité de Lisbonne","Le traité de Maastricht"],a:3,e:"Étendue par Amsterdam et Nice, elle devient la « procédure législative ordinaire » avec Lisbonne.",u:["https://fr.wikipedia.org/wiki/Proc%C3%A9dure_l%C3%A9gislative_ordinaire"],s:"Banque UE"},
{id:"ue2-043",t:"ue",q:"Lequel de ces critères ne fait pas partie des critères de convergence de Maastricht ?",o:["Un déficit public n'excédant pas 3 % du PIB","Une dette publique n'excédant pas 60 % du PIB","Une inflation proche de celle des trois États les plus performants","Un taux de chômage inférieur à 10 %"],a:3,e:"Critères : prix, déficit, dette, taux d'intérêt à long terme, stabilité du change (deux ans dans le mécanisme de change).",u:["https://fr.wikipedia.org/wiki/Crit%C3%A8res_de_convergence"],s:"Banque UE"},
{id:"ue2-044",t:"ue",q:"Quel titre a été ajouté à la Constitution en juin 1992 pour permettre la ratification du traité de Maastricht ?",o:["Un titre consacré aux Communautés européennes et à l'Union européenne","Un titre consacré à la Charte de l'environnement","Un titre consacré au Défenseur des droits","Un titre consacré à la Cour de justice de la République"],a:0,e:"Après la décision du Conseil constitutionnel du 9 avril 1992, la loi constitutionnelle du 25 juin 1992 crée ce titre, aujourd'hui titre XV « De l'Union européenne ».",u:["https://fr.wikipedia.org/wiki/Trait%C3%A9_de_Maastricht"],s:"Constitution, titre XV"},
// --- Amsterdam, Nice, traité constitutionnel, Lisbonne, TSCG ---
{id:"ue2-045",t:"ue",q:"Quand le traité d'Amsterdam est-il entré en vigueur ?",o:["2 octobre 1997","1er mai 1999","1er février 2003","1er mai 2004"],a:1,e:"Signé le 2 octobre 1997.",u:["https://fr.wikipedia.org/wiki/Trait%C3%A9_d%27Amsterdam"],s:"Banque UE"},
{id:"ue2-046",t:"ue",q:"Quel poste le traité d'Amsterdam a-t-il créé ?",o:["Le président stable du Conseil européen","Le Médiateur européen","Le procureur européen","Le haut représentant pour la PESC (« Monsieur PESC »)"],a:3,e:"Ce poste, confié au secrétaire général du Conseil, est occupé par Javier Solana de 1999 à 2009.",u:["https://fr.wikipedia.org/wiki/Trait%C3%A9_d%27Amsterdam"],s:"Banque UE"},
{id:"ue2-047",t:"ue",q:"Quel traité a introduit le mécanisme des coopérations renforcées ?",o:["Le traité d'Amsterdam","L'Acte unique européen","Le traité de Maastricht","Le traité de Lisbonne"],a:0,e:"Assoupli par Nice puis par Lisbonne (au moins neuf États).",u:["https://fr.wikipedia.org/wiki/Coop%C3%A9ration_renforc%C3%A9e"],s:"Banque UE"},
{id:"ue2-048",t:"ue",q:"Quand le traité de Nice est-il entré en vigueur ?",o:["1er mai 1999","1er février 2003","1er mai 2004","1er décembre 2009"],a:1,e:"Signé le 26 février 2001, il a été retardé par le premier « non » irlandais.",u:["https://fr.wikipedia.org/wiki/Trait%C3%A9_de_Nice"],s:"Banque UE"},
{id:"ue2-049",t:"ue",q:"Quelle réforme majeure le traité de Nice a-t-il apportée ?",o:["La création de l'euro","La clause de retrait","La repondération des voix au Conseil en vue de l'élargissement","L'élection du Parlement européen au suffrage universel"],a:2,e:"Il adapte aussi la taille de la Commission et du Parlement à l'Union élargie.",u:["https://fr.wikipedia.org/wiki/Trait%C3%A9_de_Nice"],s:"Banque UE"},
{id:"ue2-050",t:"ue",q:"Qui a présidé la Convention sur l'avenir de l'Europe (2002-2003), chargée de préparer le projet de Constitution européenne ?",o:["Jacques Delors","Jacques Chirac","Romano Prodi","Valéry Giscard d'Estaing"],a:3,e:"Avec deux vice-présidents, Giuliano Amato et Jean-Luc Dehaene.",u:["https://fr.wikipedia.org/wiki/Convention_sur_l%27avenir_de_l%27Europe"],s:"Banque UE"},
{id:"ue2-051",t:"ue",q:"Où le traité établissant une Constitution pour l'Europe a-t-il été signé le 29 octobre 2004 ?",o:["À Bruxelles","À Lisbonne","À Rome","À Nice"],a:2,e:"Au Capitole, comme les traités de 1957 ; il n'est jamais entré en vigueur.",u:["https://fr.wikipedia.org/wiki/Trait%C3%A9_%C3%A9tablissant_une_constitution_pour_l%27Europe"],s:"Banque UE"},
{id:"ue2-052",t:"ue",q:"Quelle part des suffrages exprimés le « non » a-t-il obtenue au référendum français du 29 mai 2005 ?",o:["50,9 %","54,7 %","61,5 %","68,3 %"],a:1,e:"54,67 % de non. Les Néerlandais ont rejeté le texte à 61,5 % le 1er juin 2005.",u:["https://fr.wikipedia.org/wiki/R%C3%A9f%C3%A9rendum_fran%C3%A7ais_sur_le_trait%C3%A9_%C3%A9tablissant_une_constitution_pour_l%27Europe"],s:"Banque UE"},
{id:"ue2-053",t:"ue",q:"Dans quel monument de Lisbonne le traité de Lisbonne a-t-il été signé ?",o:["Le monastère des Hiéronymites","La tour de Belém","Le palais de Belém","Le château Saint-Georges"],a:0,e:"Signature le 13 décembre 2007, sous présidence portugaise.",u:["https://fr.wikipedia.org/wiki/Trait%C3%A9_de_Lisbonne"],s:"Banque UE"},
{id:"ue2-054",t:"ue",q:"Quel pays a rejeté le traité de Lisbonne par référendum en juin 2008, avant de l'approuver en octobre 2009 ?",o:["Le Danemark","Les Pays-Bas","L'Irlande","La Tchéquie"],a:2,e:"Le second référendum a suivi des garanties, dont le maintien d'un commissaire par État.",u:["https://fr.wikipedia.org/wiki/Trait%C3%A9_de_Lisbonne"],s:"Banque UE"},
{id:"ue2-055",t:"ue",q:"Comment la France a-t-elle ratifié le traité de Lisbonne ?",o:["Par référendum, comme pour le traité de Maastricht","Par une loi votée sans révision constitutionnelle préalable","Par une ordonnance du Gouvernement","Par la voie parlementaire, après une révision constitutionnelle"],a:3,e:"Révision du 4 février 2008 au Congrès, puis loi autorisant la ratification du 13 février 2008.",u:["https://fr.wikipedia.org/wiki/Trait%C3%A9_de_Lisbonne"],s:"Banque UE"},
{id:"ue2-056",t:"ue",q:"Quel traité a doté l'Union européenne de la personnalité juridique ?",o:["Le traité de Lisbonne","Le traité de Maastricht","Le traité d'Amsterdam","Le traité de Nice"],a:0,e:"Art. 47 TUE : « L'Union a la personnalité juridique » ; elle se substitue et succède à la Communauté européenne (art. 1er TUE) et peut conclure des accords internationaux.",u:["https://fr.wikipedia.org/wiki/Trait%C3%A9_de_Lisbonne"],s:"TUE, art. 47"},
{id:"ue2-057",t:"ue",q:"Qui a été le premier président stable du Conseil européen, de 2009 à 2014 ?",o:["Herman Van Rompuy","Donald Tusk","Charles Michel","José Manuel Barroso"],a:0,e:"Ancien Premier ministre belge ; lui succèdent Donald Tusk (2014-2019), Charles Michel (2019-2024) et António Costa.",u:["https://fr.wikipedia.org/wiki/Herman_Van_Rompuy"],s:"Banque UE"},
{id:"ue2-058",t:"ue",q:"Qui a été la première haute représentante de l'Union pour les affaires étrangères et la politique de sécurité, de 2009 à 2014 ?",o:["Federica Mogherini","Kaja Kallas","Ursula von der Leyen","Catherine Ashton"],a:3,e:"Britannique, elle met en place le Service européen pour l'action extérieure.",u:["https://fr.wikipedia.org/wiki/Catherine_Ashton"],s:"Banque UE"},
{id:"ue2-059",t:"ue",q:"Quand le traité sur la stabilité, la coordination et la gouvernance (TSCG) a-t-il été signé ?",o:["7 février 1992","13 décembre 2007","2 mars 2012","1er janvier 2013"],a:2,e:"Entré en vigueur le 1er janvier 2013. Son titre III constitue le « pacte budgétaire ».",u:["https://fr.wikipedia.org/wiki/Pacte_budg%C3%A9taire_europ%C3%A9en"],s:"Banque UE"},
{id:"ue2-061",t:"ue",q:"Quelle est la nature juridique du TSCG ?",o:["Un règlement de l'Union adopté en codécision","Une directive transposée par les États membres","Un traité intergouvernemental conclu en dehors des traités de l'Union","Un protocole annexé au traité de Lisbonne"],a:2,e:"Il n'a pas été signé par tous les États, d'où le recours à un traité international distinct.",u:["https://fr.wikipedia.org/wiki/Pacte_budg%C3%A9taire_europ%C3%A9en"],s:"Banque UE"},
// --- Élargissements et retraits ---
{id:"ue2-063",t:"ue",q:"Combien d'États membres comptait la CEE après l'adhésion de l'Espagne et du Portugal en 1986 ?",o:["9","10","12","15"],a:2,e:"6 en 1957, 9 en 1973, 10 en 1981, 12 en 1986, 15 en 1995, 25 en 2004, 27 en 2007, 28 en 2013, 27 depuis 2020.",u:["https://fr.wikipedia.org/wiki/%C3%89largissement_de_l%27Union_europ%C3%A9enne"],s:"Banque UE"},
{id:"ue2-064",t:"ue",q:"Combien d'États membres l'Union a-t-elle compté au maximum ?",o:["25","27","28","29"],a:2,e:"28 entre l'adhésion de la Croatie (1er juillet 2013) et le départ du Royaume-Uni (31 janvier 2020).",u:["https://fr.wikipedia.org/wiki/%C3%89largissement_de_l%27Union_europ%C3%A9enne"],s:"Banque UE"},
{id:"ue2-065",t:"ue",q:"Quel pays a signé deux traités d'adhésion (1972 et 1994) mais a refusé à chaque fois d'adhérer par référendum ?",o:["La Suisse","La Norvège","L'Islande","Le Royaume-Uni"],a:1,e:"Les Norvégiens ont voté non en 1972 et en 1994 ; la Norvège est membre de l'Espace économique européen.",u:["https://fr.wikipedia.org/wiki/%C3%89largissement_de_l%27Union_europ%C3%A9enne"],s:"Banque UE"},
{id:"ue2-066",t:"ue",q:"En 1972, sur quoi les Français ont-ils été consultés par référendum ?",o:["Le traité de Maastricht","L'élection du Parlement européen au suffrage universel","La politique agricole commune","L'élargissement des Communautés, notamment au Royaume-Uni"],a:3,e:"Référendum du 23 avril 1972 voulu par Georges Pompidou : 68,32 % de oui.",u:["https://fr.wikipedia.org/wiki/R%C3%A9f%C3%A9rendum_fran%C3%A7ais_sur_l%27%C3%A9largissement_des_Communaut%C3%A9s_europ%C3%A9ennes"],s:"Banque UE"},
{id:"ue2-067",t:"ue",q:"Lequel de ces pays n'a pas adhéré à l'Union européenne le 1er mai 2004 ?",o:["La Roumanie","La Slovénie","Malte","La Lituanie"],a:0,e:"En 2004 : Chypre, Estonie, Hongrie, Lettonie, Lituanie, Malte, Pologne, Tchéquie, Slovaquie, Slovénie. La Roumanie adhère en 2007.",u:["https://fr.wikipedia.org/wiki/%C3%89largissement_de_l%27Union_europ%C3%A9enne"],s:"Banque UE"},
{id:"ue2-068",t:"ue",q:"Dans quelle ville a été signé, le 16 avril 2003, le traité d'adhésion des dix pays entrés dans l'Union en 2004 ?",o:["Copenhague","Athènes","Varsovie","Nice"],a:1,e:"Au portique d'Attale, sous présidence grecque ; les négociations avaient été conclues à Copenhague en décembre 2002.",u:["https://fr.wikipedia.org/wiki/%C3%89largissement_de_l%27Union_europ%C3%A9enne"],s:"Banque UE"},
{id:"ue2-069",t:"ue",q:"À quelle date la Croatie a-t-elle adhéré à l'Union européenne ?",o:["1er janvier 2007","1er juillet 2013","1er janvier 2015","1er janvier 2023"],a:1,e:"28e État membre ; elle a rejoint l'euro et Schengen le 1er janvier 2023.",u:["https://fr.wikipedia.org/wiki/Adh%C3%A9sion_de_la_Croatie_%C3%A0_l%27Union_europ%C3%A9enne"],s:"Banque UE"},
{id:"ue2-070",t:"ue",q:"Comment le territoire de l'ancienne RDA est-il entré dans les Communautés européennes ?",o:["Par un traité d'adhésion signé en 1995","Lors de l'élargissement de 2004","Par la réunification allemande du 3 octobre 1990, sans traité d'adhésion","Il n'y est jamais entré"],a:2,e:"Le territoire de la RFA s'étant étendu, le droit communautaire s'y est appliqué sans nouvel État membre.",u:["https://fr.wikipedia.org/wiki/%C3%89largissement_de_l%27Union_europ%C3%A9enne"],s:"Banque UE"},
{id:"ue2-071",t:"ue",q:"Quel territoire a quitté les Communautés européennes en 1985, à la suite d'un référendum ?",o:["Le Groenland","Les îles Féroé","L'Islande","Les îles Åland"],a:0,e:"Après le référendum de 1982, le Groenland, territoire autonome danois, sort le 1er février 1985. Les Féroé n'y sont jamais entrées.",u:["https://fr.wikipedia.org/wiki/Groenland"],s:"Banque UE"},
{id:"ue2-072",t:"ue",q:"Quel est aujourd'hui le statut du Groenland vis-à-vis de l'Union européenne ?",o:["Une région ultrapériphérique","Un pays candidat à l'adhésion","Une partie intégrante du territoire de l'Union","Un pays et territoire d'outre-mer (PTOM)"],a:3,e:"Les PTOM ne font pas partie du territoire de l'Union mais lui sont associés (TFUE, quatrième partie).",u:["https://fr.wikipedia.org/wiki/Pays_et_territoires_d%27outre-mer"],s:"Banque UE"},
{id:"ue2-073",t:"ue",q:"Quel a été le résultat du référendum britannique du 23 juin 2016 ?",o:["Environ 52 % pour le maintien","Environ 52 % pour la sortie","Environ 67 % pour la sortie","Environ 48 % pour la sortie"],a:1,e:"51,9 % pour le « Leave », contre 48,1 % pour le « Remain ».",u:["https://fr.wikipedia.org/wiki/R%C3%A9f%C3%A9rendum_sur_l%27appartenance_du_Royaume-Uni_%C3%A0_l%27Union_europ%C3%A9enne"],s:"Banque UE"},
{id:"ue2-074",t:"ue",q:"Quand le Royaume-Uni a-t-il notifié son intention de se retirer de l'Union, déclenchant l'article 50 TUE ?",o:["23 juin 2016","29 mars 2017","31 janvier 2020","1er janvier 2021"],a:1,e:"Lettre de Theresa May ; la sortie, plusieurs fois reportée, intervient le 31 janvier 2020.",u:["https://fr.wikipedia.org/wiki/Brexit"],s:"Banque UE"},
{id:"ue2-075",t:"ue",q:"Sauf prorogation, quel délai l'article 50 TUE prévoit-il entre la notification et la sortie de l'État ?",o:["6 mois","1 an","2 ans","5 ans"],a:2,e:"Faute d'accord de retrait, les traités cessent de s'appliquer deux ans après la notification.",u:["https://fr.wikipedia.org/wiki/Article_50_du_trait%C3%A9_sur_l%27Union_europ%C3%A9enne"],s:"TUE, art. 50"},
{id:"ue2-076",t:"ue",q:"Qui peut proroger le délai de négociation prévu par l'article 50 TUE ?",o:["Le Conseil européen, à l'unanimité et en accord avec l'État concerné","La Commission seule","Le Parlement européen à la majorité simple","La Cour de justice de l'Union"],a:0,e:"Pour le Brexit, l'échéance du 29 mars 2019 a été reportée au 12 avril, au 31 octobre 2019, puis au 31 janvier 2020.",u:["https://fr.wikipedia.org/wiki/Article_50_du_trait%C3%A9_sur_l%27Union_europ%C3%A9enne"],s:"TUE, art. 50"},
{id:"ue2-077",t:"ue",q:"Comment l'accord de retrait est-il conclu au nom de l'Union selon l'article 50 TUE ?",o:["Par le Conseil à l'unanimité, puis ratification par tous les États","Par la Commission seule","Par le Conseil à la majorité qualifiée, après approbation du Parlement européen","Par référendum dans chaque État membre"],a:2,e:"Contrairement à un traité d'adhésion, il n'exige ni unanimité ni ratifications nationales.",u:["https://fr.wikipedia.org/wiki/Article_50_du_trait%C3%A9_sur_l%27Union_europ%C3%A9enne"],s:"TUE, art. 50"},
{id:"ue2-078",t:"ue",q:"Un État qui s'est retiré de l'Union peut-il demander à nouveau son adhésion ?",o:["Non, jamais","Oui, mais seulement après un délai de dix ans","Oui, par simple notification au Conseil européen","Oui, selon la procédure d'adhésion de l'article 49 TUE"],a:3,e:"Art. 50, paragraphe 5, TUE.",u:["https://fr.wikipedia.org/wiki/Article_50_du_trait%C3%A9_sur_l%27Union_europ%C3%A9enne"],s:"TUE, art. 50"},
{id:"ue2-079",t:"ue",q:"Qui a été le négociateur en chef de l'Union européenne pour le Brexit ?",o:["Pierre Moscovici","Jean-Claude Juncker","Michel Barnier","Donald Tusk"],a:2,e:"Il conduit la négociation de l'accord de retrait puis de l'accord de commerce et de coopération (2016-2021).",u:["https://fr.wikipedia.org/wiki/Michel_Barnier"],s:"Banque UE"},
{id:"ue2-080",t:"ue",q:"Quel accord régit depuis le 1er janvier 2021 les relations entre l'Union européenne et le Royaume-Uni ?",o:["L'accord de commerce et de coopération","L'accord sur l'Espace économique européen","L'accord de Schengen","Un accord d'union douanière"],a:0,e:"Signé le 30 décembre 2020, appliqué à la fin de la période de transition ; il prévoit un libre-échange sans droits de douane ni quotas.",u:["https://fr.wikipedia.org/wiki/Accord_de_commerce_et_de_coop%C3%A9ration_entre_le_Royaume-Uni_et_l%27Union_europ%C3%A9enne"],s:"Banque UE"},
// --- Candidats et processus d'adhésion ---
{id:"ue2-081",t:"ue",q:"Selon l'article 49 TUE, quel État peut demander à devenir membre de l'Union ?",o:["Tout État membre de l'ONU qui en fait la demande","Tout État européen qui respecte les valeurs de l'article 2 TUE et s'engage à les promouvoir","Tout État membre du Conseil de l'Europe, sans autre condition","Tout État ayant déjà adopté l'euro"],a:1,e:"La demande est adressée au Conseil ; le Parlement européen et les parlements nationaux en sont informés.",u:["https://fr.wikipedia.org/wiki/%C3%89largissement_de_l%27Union_europ%C3%A9enne"],s:"TUE, art. 49"},
{id:"ue2-082",t:"ue",q:"Après sa signature, comment un traité d'adhésion entre-t-il en vigueur ?",o:["Dès l'approbation du Parlement européen","Après un vote à la majorité qualifiée du Conseil","Après un référendum européen","Après ratification par tous les États membres et par l'État candidat"],a:3,e:"Chaque État ratifie selon ses règles constitutionnelles (art. 49 TUE).",u:["https://fr.wikipedia.org/wiki/%C3%89largissement_de_l%27Union_europ%C3%A9enne"],s:"TUE, art. 49"},
{id:"ue2-083",t:"ue",q:"En combien de chapitres l'acquis de l'Union est-il découpé pour les négociations d'adhésion ?",o:["12","27","35","50"],a:2,e:"Depuis 2020, ces chapitres sont regroupés en six « clusters » ; le cluster « fondamentaux » est ouvert en premier et fermé en dernier.",u:["https://fr.wikipedia.org/wiki/%C3%89largissement_de_l%27Union_europ%C3%A9enne"],s:"Banque UE"},
{id:"ue2-084",t:"ue",q:"Qui décide d'accorder à un pays le statut de candidat à l'adhésion ?",o:["La Commission européenne seule","Le Conseil européen, à l'unanimité des États membres","Le Parlement européen","La Cour de justice de l'Union"],a:1,e:"La Commission rend un avis préalable. L'Ukraine et la Moldavie ont obtenu ce statut au Conseil européen de juin 2022.",u:["https://fr.wikipedia.org/wiki/%C3%89largissement_de_l%27Union_europ%C3%A9enne"],s:"Banque UE"},
{id:"ue2-085",t:"ue",q:"En quelle année la Turquie a-t-elle déposé sa demande d'adhésion aux Communautés européennes ?",o:["1963","1987","1999","2005"],a:1,e:"1963 : accord d'association d'Ankara ; 1999 : statut de candidat ; 2005 : ouverture des négociations, que le Conseil a déclarées « au point mort » en 2018.",u:["https://fr.wikipedia.org/wiki/Adh%C3%A9sion_de_la_Turquie_%C3%A0_l%27Union_europ%C3%A9enne"],s:"Banque UE"},
{id:"ue2-086",t:"ue",q:"Lors de quel Conseil européen la Turquie a-t-elle obtenu le statut de candidat ?",o:["Helsinki, en décembre 1999","Copenhague, en juin 1993","Luxembourg, en décembre 1997","Thessalonique, en juin 2003"],a:0,e:"Le Conseil européen de Luxembourg de 1997 ne l'avait pas retenue parmi les candidats.",u:["https://fr.wikipedia.org/wiki/Adh%C3%A9sion_de_la_Turquie_%C3%A0_l%27Union_europ%C3%A9enne"],s:"Banque UE"},
{id:"ue2-087",t:"ue",q:"Quelle demande d'adhésion a été rejetée en 1987 au motif que le pays n'était pas européen ?",o:["Celle de la Turquie","Celle de la Tunisie","Celle de Chypre","Celle du Maroc"],a:3,e:"L'article 49 TUE réserve l'adhésion aux États européens.",s:"Banque UE"},
{id:"ue2-088",t:"ue",q:"Quel autre pays a obtenu le statut de candidat en même temps que l'Ukraine, en juin 2022 ?",o:["La Géorgie","La Bosnie-Herzégovine","La Moldavie","L'Arménie"],a:2,e:"La Bosnie-Herzégovine l'a obtenu en décembre 2022, la Géorgie en décembre 2023. Les négociations avec l'Ukraine et la Moldavie ont été ouvertes en juin 2024.",u:["https://fr.wikipedia.org/wiki/Relations_entre_la_Moldavie_et_l%27Union_europ%C3%A9enne"],s:"Banque UE"},
{id:"ue2-089",t:"ue",q:"Quand la Géorgie a-t-elle obtenu le statut de pays candidat ?",o:["Juin 2008","Juin 2022","Décembre 2023","Mars 2025"],a:2,e:"Statut accordé par le Conseil européen du 14 décembre 2023 ; le processus est de fait à l'arrêt depuis 2024.",u:["https://fr.wikipedia.org/wiki/Relations_entre_la_G%C3%A9orgie_et_l%27Union_europ%C3%A9enne"],s:"Banque UE"},
{id:"ue2-090",t:"ue",q:"Lequel de ces pays a obtenu le statut de candidat en 2010 et ouvert ses négociations d'adhésion en 2012 ?",o:["Le Kosovo","La Bosnie-Herzégovine","Le Monténégro","La Géorgie"],a:2,e:"La Serbie a ouvert les siennes en 2014, l'Albanie et la Macédoine du Nord en 2022.",u:["https://fr.wikipedia.org/wiki/Adh%C3%A9sion_du_Mont%C3%A9n%C3%A9gro_%C3%A0_l%27Union_europ%C3%A9enne"],s:"Banque UE"},
{id:"ue2-091",t:"ue",q:"Quel accord de 2018 a réglé le différend sur le nom de la Macédoine du Nord, ouvrant la voie à ses négociations d'adhésion ?",o:["L'accord de Dayton","L'accord d'Ohrid","L'accord de Bruxelles","L'accord de Prespa"],a:3,e:"Conclu avec la Grèce ; Dayton (1995) concerne la Bosnie, Ohrid (2001) la paix civile en Macédoine.",u:["https://fr.wikipedia.org/wiki/Accord_de_Prespa"],s:"Banque UE"},
{id:"ue2-092",t:"ue",q:"En quelle année le Kosovo a-t-il déposé sa demande d'adhésion à l'Union européenne ?",o:["2008","2013","2022","2025"],a:2,e:"Demande du 15 décembre 2022 ; cinq États membres (Espagne, Grèce, Chypre, Roumanie, Slovaquie) ne reconnaissent pas son indépendance.",u:["https://fr.wikipedia.org/wiki/Relations_entre_le_Kosovo_et_l%27Union_europ%C3%A9enne"],s:"Banque UE"},
{id:"ue2-093",t:"ue",q:"Quel pays a déposé une demande d'adhésion en 2009 avant de la retirer en 2015 ?",o:["La Norvège","L'Islande","La Suisse","La Serbie"],a:1,e:"Candidature déposée après la crise bancaire de 2008, gelée en 2013 puis retirée.",u:["https://fr.wikipedia.org/wiki/Adh%C3%A9sion_de_l%27Islande_%C3%A0_l%27Union_europ%C3%A9enne"],s:"Banque UE"},
{id:"ue2-094",t:"ue",q:"Quel Conseil européen de 2003 a reconnu la « perspective européenne » des pays des Balkans occidentaux ?",o:["Thessalonique","Helsinki","Laeken","Copenhague"],a:0,e:"Juin 2003, dans le cadre du processus de stabilisation et d'association lancé en 1999.",u:["https://fr.wikipedia.org/wiki/Sommet_de_Thessalonique"],s:"Banque UE"},
{id:"ue2-095",t:"ue",q:"Selon l'article 88-5 de la Constitution, comment est en principe autorisée la ratification d'un traité d'adhésion d'un nouvel État à l'Union ?",o:["Par référendum, sauf si le Parlement choisit la voie du Congrès par une motion votée aux trois cinquièmes","Par une loi ordinaire votée par les deux assemblées, sans autre formalité","Par un décret du Président de la République pris en Conseil des ministres","Par une décision du Conseil constitutionnel saisi par le Premier ministre"],a:0,e:"Disposition de 2005, assouplie en 2008 ; elle ne s'applique pas aux adhésions issues d'une conférence intergouvernementale convoquée avant le 1er juillet 2004.",u:["https://fr.wikipedia.org/wiki/Constitution_fran%C3%A7aise_du_4_octobre_1958"],s:"Constitution, art. 88-5"},
{id:"ue2-096",t:"ue",q:"Quel forum, réunissant des États européens membres et non membres de l'UE, s'est réuni pour la première fois à Prague en octobre 2022 ?",o:["Le Conseil de l'Europe","Le Partenariat oriental","La Communauté politique européenne","L'Union pour la Méditerranée"],a:2,e:"Proposée par Emmanuel Macron, elle réunit plus de quarante pays, dont le Royaume-Uni, la Turquie et l'Ukraine.",u:["https://fr.wikipedia.org/wiki/Communaut%C3%A9_politique_europ%C3%A9enne"],s:"Banque UE"},
{id:"ue2-097",t:"ue",q:"Quels pays forment, avec les États de l'Union, l'Espace économique européen ?",o:["La Suisse, la Norvège et l'Islande","L'Islande, le Liechtenstein et la Norvège","Le Royaume-Uni, la Suisse et la Norvège","L'Islande, la Norvège et la Turquie"],a:1,e:"EEE en vigueur depuis 1994 ; la Suisse l'a refusé par référendum en 1992 et est liée à l'Union par des accords bilatéraux.",u:["https://fr.wikipedia.org/wiki/Espace_%C3%A9conomique_europ%C3%A9en"],s:"Banque UE"},
// --- États membres, euro et territoires ---
{id:"ue2-098",t:"ue",q:"Quelle est la capitale de la Slovénie ?",o:["Bratislava","Zagreb","Skopje","Ljubljana"],a:3,e:"Bratislava est la capitale de la Slovaquie, Zagreb celle de la Croatie, Skopje celle de la Macédoine du Nord.",u:["https://fr.wikipedia.org/wiki/Ljubljana"],s:"Banque UE"},
{id:"ue2-099",t:"ue",q:"Quelle est la capitale de la Lituanie, État qui présidera le Conseil de l'UE au premier semestre 2027 ?",o:["Riga","Tallinn","Vilnius","Minsk"],a:2,e:"Riga est la capitale de la Lettonie, Tallinn celle de l'Estonie, Minsk celle de la Biélorussie.",u:["https://fr.wikipedia.org/wiki/Vilnius"],s:"Banque UE",act:1},
{id:"ue2-100",t:"ue",q:"Quel est l'État membre le moins peuplé de l'Union européenne ?",o:["Malte","Le Luxembourg","Chypre","L'Estonie"],a:0,e:"Un peu plus d'un demi-million d'habitants ; l'Allemagne est le plus peuplé.",s:"Banque UE"},
{id:"ue2-101",t:"ue",q:"Combien d'États ont adopté l'euro dès le 1er janvier 1999 ?",o:["6","11","12","15"],a:1,e:"Allemagne, Autriche, Belgique, Espagne, Finlande, France, Irlande, Italie, Luxembourg, Pays-Bas, Portugal ; la Grèce suit en 2001.",u:["https://fr.wikipedia.org/wiki/Zone_euro"],s:"Banque UE"},
{id:"ue2-102",t:"ue",q:"Quel État membre bénéficie d'une clause d'exemption (opt-out) le dispensant d'adopter l'euro ?",o:["La Suède","Le Danemark","La Pologne","La Hongrie"],a:1,e:"Les autres États hors zone euro (dont la Suède, la Pologne et la Hongrie) sont « à dérogation » et ont vocation à l'adopter.",u:["https://fr.wikipedia.org/wiki/Zone_euro"],s:"Banque UE"},
{id:"ue2-103",t:"ue",q:"Combien d'États membres de l'Union n'utilisent pas l'euro en 2026 ?",o:["5","6","7","8"],a:1,e:"Danemark, Suède, Pologne, Tchéquie, Hongrie et Roumanie ; la zone euro compte 21 membres depuis le 1er janvier 2026.",u:["https://fr.wikipedia.org/wiki/Zone_euro"],s:"Banque UE",act:1},
{id:"ue2-104",t:"ue",q:"Lequel de ces États non membres de l'Union utilise l'euro en vertu d'un accord monétaire avec l'Union ?",o:["La Suisse","La Norvège","Le Royaume-Uni","Monaco"],a:3,e:"Andorre, Saint-Marin et le Vatican ont aussi un accord ; le Monténégro et le Kosovo utilisent l'euro sans accord.",u:["https://fr.wikipedia.org/wiki/Euro"],s:"Banque UE"},
{id:"ue2-105",t:"ue",q:"Dans quel mécanisme un État doit-il avoir participé au moins deux ans avant d'adopter l'euro ?",o:["Le mécanisme de change européen (MCE II)","Le Mécanisme européen de stabilité","Le mécanisme de surveillance unique","Le semestre européen"],a:0,e:"Critère de stabilité du change, sans dévaluation ni tension grave.",u:["https://fr.wikipedia.org/wiki/M%C3%A9canisme_de_change_europ%C3%A9en"],s:"Banque UE"},
{id:"ue2-106",t:"ue",q:"Qui décide qu'un État membre remplit les conditions pour adopter l'euro ?",o:["La BCE seule","Le Parlement européen seul","Le Conseil de l'UE, sur proposition de la Commission","L'État lui-même par référendum"],a:2,e:"Art. 140 TFUE : après consultation du Parlement et discussion au Conseil européen, sur la base des rapports de convergence de la Commission et de la BCE.",u:["https://fr.wikipedia.org/wiki/Zone_euro"],s:"TFUE, art. 140"},
{id:"ue2-107",t:"ue",q:"Combien de régions ultrapériphériques l'Union européenne compte-t-elle ?",o:["6","9","12","13"],a:1,e:"Guadeloupe, Guyane, Martinique, Mayotte, La Réunion, Saint-Martin, les Açores, Madère et les Canaries (art. 349 TFUE).",u:["https://fr.wikipedia.org/wiki/R%C3%A9gion_ultrap%C3%A9riph%C3%A9rique"],s:"TFUE, art. 349"},
{id:"ue2-108",t:"ue",q:"Depuis quand Mayotte est-elle une région ultrapériphérique de l'Union ?",o:["1er janvier 2011","1er janvier 2014","1er janvier 2019","Elle n'en est pas une"],a:1,e:"Elle était auparavant un pays et territoire d'outre-mer ; le droit de l'Union s'y applique depuis le 1er janvier 2014.",u:["https://fr.wikipedia.org/wiki/R%C3%A9gion_ultrap%C3%A9riph%C3%A9rique"],s:"Banque UE"},
{id:"ue2-109",t:"ue",q:"Quel territoire français a quitté en 2012 le statut de région ultrapériphérique pour devenir un pays et territoire d'outre-mer ?",o:["Saint-Martin","Mayotte","La Réunion","Saint-Barthélemy"],a:3,e:"Depuis le 1er janvier 2012, le droit de l'Union ne s'y applique plus, mais l'euro y reste la monnaie.",u:["https://fr.wikipedia.org/wiki/Pays_et_territoires_d%27outre-mer"],s:"Banque UE"},
// --- Institutions : vue d'ensemble ---
{id:"ue2-110",t:"ue",q:"Depuis quel traité la Cour des comptes européenne a-t-elle le rang d'institution ?",o:["Le traité de Rome","Le traité de Maastricht","Le traité de Lisbonne","Le traité de Nice"],a:1,e:"Créée par le traité de Bruxelles du 22 juillet 1975, elle fonctionne depuis 1977 et devient institution en 1993.",u:["https://fr.wikipedia.org/wiki/Cour_des_comptes_europ%C3%A9enne"],s:"Banque UE"},
// --- Parlement européen ---
{id:"ue2-111",t:"ue",q:"Combien de sièges le TUE autorise-t-il au maximum au Parlement européen, président compris ?",o:["720","736","751","785"],a:2,e:"750 députés plus le président (art. 14 TUE) ; la législature 2024-2029 en compte 720.",u:["https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/european-parliament_fr"],s:"TUE, art. 14"},
{id:"ue2-112",t:"ue",q:"Selon le TUE, quels sont le nombre minimal et le nombre maximal de sièges par État au Parlement européen ?",o:["6 et 96","1 et 100","5 et 99","6 et 81"],a:0,e:"Malte, le Luxembourg et Chypre ont 6 sièges, l'Allemagne 96.",u:["https://fr.wikipedia.org/wiki/Parlement_europ%C3%A9en"],s:"TUE, art. 14"},
{id:"ue2-113",t:"ue",q:"Quel État membre élit le plus de députés européens ?",o:["La France","L'Italie","L'Allemagne","La Pologne"],a:2,e:"96 sièges, devant la France (81), l'Italie (76), l'Espagne (61) et la Pologne (53).",u:["https://fr.wikipedia.org/wiki/%C3%89lections_europ%C3%A9ennes_de_2024"],s:"Banque UE"},
{id:"ue2-114",t:"ue",q:"Selon quel principe les sièges du Parlement européen sont-ils répartis entre les États ?",o:["L'égalité stricte entre États","La proportionnalité exacte à la population","Le montant de la contribution au budget","La proportionnalité dégressive"],a:3,e:"Un député d'un petit État représente moins d'habitants qu'un député d'un grand État.",u:["https://fr.wikipedia.org/wiki/Parlement_europ%C3%A9en"],s:"TUE, art. 14"},
{id:"ue2-115",t:"ue",q:"Comment les députés européens sont-ils élus en France depuis 2019 ?",o:["Au scrutin majoritaire uninominal à deux tours","Au scrutin de liste proportionnel, dans une circonscription nationale unique","Au scrutin de liste dans huit circonscriptions interrégionales","Par les députés et les sénateurs"],a:1,e:"La loi du 25 juin 2018 a supprimé les huit circonscriptions interrégionales utilisées de 2004 à 2014.",u:["https://fr.wikipedia.org/wiki/%C3%89lections_europ%C3%A9ennes_de_2024_en_France"],s:"Banque UE"},
{id:"ue2-116",t:"ue",q:"Quel pourcentage des suffrages exprimés une liste doit-elle obtenir en France pour avoir des élus au Parlement européen ?",o:["3 %","5 %","10 %","12,5 %"],a:1,e:"Les sièges sont répartis à la proportionnelle à la plus forte moyenne entre les listes ayant au moins 5 %.",u:["https://fr.wikipedia.org/wiki/%C3%89lections_europ%C3%A9ennes_de_2024_en_France"],s:"Banque UE"},
{id:"ue2-117",t:"ue",q:"Pour quelle durée le président du Parlement européen est-il élu ?",o:["6 mois","1 an","2 ans et demi","5 ans"],a:2,e:"Il est élu par les députés pour la moitié de la législature, et peut être réélu (Roberta Metsola, 2022 puis 2024).",u:["https://fr.wikipedia.org/wiki/Pr%C3%A9sident_du_Parlement_europ%C3%A9en"],s:"Banque UE"},
{id:"ue2-118",t:"ue",q:"Combien de périodes de session plénière mensuelles le Parlement européen doit-il tenir chaque année à Strasbourg ?",o:["4","10","12","24"],a:2,e:"Protocole sur les sièges : douze sessions à Strasbourg, dont la session budgétaire ; des sessions additionnelles se tiennent à Bruxelles.",u:["https://fr.wikipedia.org/wiki/Parlement_europ%C3%A9en"],s:"Banque UE"},
{id:"ue2-119",t:"ue",q:"Quel groupe politique est le plus nombreux au Parlement européen élu en 2024 ?",o:["Les Socialistes et démocrates (S&D)","Renew Europe","Les Patriotes pour l'Europe","Le Parti populaire européen (PPE)"],a:3,e:"Le PPE est le premier groupe depuis 1999 ; il compte environ 188 députés en 2024, devant les S&D.",u:["https://fr.wikipedia.org/wiki/Parlement_europ%C3%A9en"],s:"Banque UE"},
{id:"ue2-120",t:"ue",q:"Quelles conditions faut-il remplir pour former un groupe politique au Parlement européen ?",o:["Réunir au moins 10 députés d'un même État","Réunir au moins 50 députés","Réunir au moins 23 députés élus dans au moins un quart des États membres","Réunir au moins 23 députés d'un même parti national"],a:2,e:"Règlement intérieur du Parlement ; un quart des États représente aujourd'hui 7 États.",u:["https://fr.wikipedia.org/wiki/Parlement_europ%C3%A9en"],s:"Banque UE"},
{id:"ue2-121",t:"ue",q:"Que désigne le système des « Spitzenkandidaten » ?",o:["La désignation par chaque parti européen, avant les élections, de son candidat à la présidence de la Commission","L'élection directe du président du Conseil européen par les citoyens","La désignation de la tête de liste nationale de chaque parti","Le choix du doyen d'âge qui préside la séance inaugurale du Parlement"],a:0,e:"Appliqué en 2014 (Jean-Claude Juncker) ; non suivi en 2019, Ursula von der Leyen n'ayant pas été la candidate d'un parti européen.",u:["https://fr.wikipedia.org/wiki/Spitzenkandidat"],s:"Banque UE"},
{id:"ue2-122",t:"ue",q:"Quel prix le Parlement européen décerne-t-il chaque année pour la liberté de l'esprit ?",o:["Le prix Charlemagne","Le prix Sakharov","Le prix Nobel de la paix","Le prix Princesse des Asturies"],a:1,e:"Créé en 1988 ; le prix Charlemagne est décerné par la ville d'Aix-la-Chapelle.",u:["https://fr.wikipedia.org/wiki/Prix_Sakharov"],s:"Banque UE"},
{id:"ue2-123",t:"ue",q:"Dans quel cas le Parlement européen doit-il donner son approbation ?",o:["Pour l'adoption des directives d'harmonisation de la TVA","Pour la nomination des juges de la Cour de justice","Pour la fixation des taux directeurs de la BCE","Pour l'adhésion d'un nouvel État membre"],a:3,e:"La procédure d'approbation vaut aussi pour la plupart des accords internationaux et le cadre financier pluriannuel ; en matière de TVA, il est seulement consulté.",u:["https://fr.wikipedia.org/wiki/Parlement_europ%C3%A9en"],s:"TUE, art. 49"},
{id:"ue2-124",t:"ue",q:"Quelle institution donne décharge à la Commission sur l'exécution du budget de l'Union ?",o:["La Cour des comptes européenne","Le Parlement européen, sur recommandation du Conseil","Le Conseil européen","La Cour de justice de l'Union"],a:1,e:"Art. 319 TFUE ; il s'appuie sur le rapport annuel de la Cour des comptes européenne.",u:["https://fr.wikipedia.org/wiki/Parlement_europ%C3%A9en"],s:"TFUE, art. 319"},
{id:"ue2-125",t:"ue",q:"Qui peut adresser une pétition au Parlement européen ?",o:["Tout citoyen de l'Union et toute personne résidant dans un État membre","Seuls les parlements nationaux","Seuls les députés européens","Seules les associations agréées par la Commission"],a:0,e:"Art. 227 TFUE (personnes morales comprises), sur un sujet relevant des domaines d'activité de l'Union qui la concerne directement.",u:["https://fr.wikipedia.org/wiki/Citoyennet%C3%A9_de_l%27Union_europ%C3%A9enne"],s:"TFUE, art. 227"},
{id:"ue2-126",t:"ue",q:"Comment le Parlement européen peut-il intervenir dans l'initiative législative ?",o:["Il dispose d'un droit d'initiative identique à celui de la Commission","Il ne peut en aucun cas intervenir avant la proposition","Il peut demander à la Commission de soumettre une proposition, à la majorité de ses membres","Il peut adopter seul un règlement, sans proposition"],a:2,e:"Art. 225 TFUE : si la Commission ne présente pas de proposition, elle doit en communiquer les raisons.",u:["https://fr.wikipedia.org/wiki/Parlement_europ%C3%A9en"],s:"TFUE, art. 225"},
{id:"ue2-127",t:"ue",q:"Quelle majorité est requise au Parlement européen pour élire le président de la Commission ?",o:["La majorité des suffrages exprimés","Les deux tiers des membres","La majorité des membres qui le composent","L'accord de tous les présidents de groupe"],a:2,e:"Soit 361 voix sur 720 ; à défaut, le Conseil européen propose un nouveau candidat dans le délai d'un mois.",u:["https://fr.wikipedia.org/wiki/Pr%C3%A9sident_de_la_Commission_europ%C3%A9enne"],s:"TUE, art. 17"},
{id:"ue2-128",t:"ue",q:"Qui est la première femme à présider la Commission européenne ?",o:["Roberta Metsola","Christine Lagarde","Kaja Kallas","Ursula von der Leyen"],a:3,e:"Présidente depuis le 1er décembre 2019, reconduite en 2024 ; ancienne ministre allemande de la Défense.",u:["https://fr.wikipedia.org/wiki/Ursula_von_der_Leyen"],s:"Banque UE"},
// --- Conseil européen ---
{id:"ue2-129",t:"ue",q:"Combien de fois au minimum le Conseil européen se réunit-il chaque année selon le TUE ?",o:["Une fois par an","Deux fois par semestre","Une fois par mois","Chaque semaine"],a:1,e:"Soit au moins quatre réunions par an, à Bruxelles ; son président peut convoquer des réunions extraordinaires.",u:["https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/european-council_fr"],s:"TUE, art. 15"},
{id:"ue2-130",t:"ue",q:"Sauf disposition contraire des traités, comment le Conseil européen se prononce-t-il ?",o:["Par consensus","À la majorité simple","À la majorité des deux tiers","Par un vote pondéré selon le PIB"],a:0,e:"Art. 15, paragraphe 4, TUE. Il statue toutefois à la majorité qualifiée pour certaines nominations.",u:["https://fr.wikipedia.org/wiki/Conseil_europ%C3%A9en"],s:"TUE, art. 15"},
{id:"ue2-131",t:"ue",q:"Qui élit le président du Conseil européen ?",o:["Le Conseil européen, à la majorité qualifiée","Le Parlement européen","Les citoyens européens","Le Conseil de l'UE à l'unanimité"],a:0,e:"Pour deux ans et demi, renouvelable une fois ; António Costa exerce cette fonction depuis le 1er décembre 2024.",u:["https://fr.wikipedia.org/wiki/Conseil_europ%C3%A9en"],s:"TUE, art. 15"},
{id:"ue2-132",t:"ue",q:"Le président du Conseil européen peut-il exercer en même temps un mandat national ?",o:["Oui, s'il est chef de gouvernement","Oui, avec l'accord du Parlement européen","Oui, s'il est ministre des Affaires étrangères","Non, le TUE l'interdit"],a:3,e:"Art. 15, paragraphe 6, TUE.",u:["https://fr.wikipedia.org/wiki/Conseil_europ%C3%A9en"],s:"TUE, art. 15"},
{id:"ue2-133",t:"ue",q:"Qui représente la France au Conseil européen ?",o:["Le Premier ministre","Le Président de la République","Le ministre de l'Europe et des Affaires étrangères","Le ministre chargé des affaires européennes"],a:1,e:"Le Conseil européen réunit les chefs d'État ou de gouvernement selon l'organisation de chaque État.",u:["https://fr.wikipedia.org/wiki/Conseil_europ%C3%A9en"],s:"Banque UE"},
{id:"ue2-134",t:"ue",q:"Comment le haut représentant de l'Union pour les affaires étrangères est-il nommé ?",o:["Par le Parlement européen seul","Par le Conseil de l'UE à l'unanimité","Par le Conseil européen, à la majorité qualifiée, avec l'accord du président de la Commission","Par le président de la Commission seul"],a:2,e:"Art. 18 TUE ; vice-président de la Commission, il est aussi soumis au vote d'approbation du collège par le Parlement.",u:["https://fr.wikipedia.org/wiki/Haut_repr%C3%A9sentant_de_l%27Union_pour_les_affaires_%C3%A9trang%C3%A8res_et_la_politique_de_s%C3%A9curit%C3%A9"],s:"TUE, art. 18"},
{id:"ue2-135",t:"ue",q:"Outre ses fonctions en matière de PESC, le haut représentant de l'Union est également :",o:["Président du Conseil européen","Vice-président de la Commission européenne","Président de l'Eurogroupe","Vice-président du Parlement européen"],a:1,e:"Cette « double casquette » existe depuis Lisbonne ; Kaja Kallas occupe le poste depuis le 1er décembre 2024.",u:["https://fr.wikipedia.org/wiki/Haut_repr%C3%A9sentant_de_l%27Union_pour_les_affaires_%C3%A9trang%C3%A8res_et_la_politique_de_s%C3%A9curit%C3%A9"],s:"TUE, art. 18"},
{id:"ue2-136",t:"ue",q:"Quel service diplomatique de l'Union, créé par le traité de Lisbonne, est placé sous l'autorité du haut représentant ?",o:["Le Comité politique et de sécurité","Eurojust","Le Coreper","Le Service européen pour l'action extérieure"],a:3,e:"Opérationnel depuis 2011, il gère notamment les délégations de l'Union dans le monde.",u:["https://fr.wikipedia.org/wiki/Service_europ%C3%A9en_pour_l%27action_ext%C3%A9rieure"],s:"Banque UE"},
// --- Conseil de l'Union européenne ---
{id:"ue2-137",t:"ue",q:"Combien de formations le Conseil de l'Union européenne compte-t-il ?",o:["5","10","15","27"],a:1,e:"Dont Affaires générales, Affaires étrangères, ECOFIN, Justice et affaires intérieures, Agriculture et pêche, Environnement, Compétitivité.",u:["https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/council-european-union_fr"],s:"Banque UE"},
{id:"ue2-138",t:"ue",q:"Quelle formation du Conseil de l'UE réunit les ministres de l'Économie et des Finances ?",o:["Le Conseil ECOFIN","Le Conseil « Compétitivité »","Le Conseil « Affaires générales »","Le Coreper"],a:0,e:"Il traite notamment de la fiscalité, de la surveillance budgétaire et du budget de l'Union.",u:["https://fr.wikipedia.org/wiki/Conseil_de_l%27Union_europ%C3%A9enne"],s:"Banque UE"},
{id:"ue2-139",t:"ue",q:"Qui préside le Conseil « Affaires étrangères » ?",o:["Le ministre de l'État qui exerce la présidence tournante","Le président du Conseil européen","Le haut représentant de l'Union pour les affaires étrangères et la politique de sécurité","Le président de la Commission"],a:2,e:"C'est la seule formation du Conseil qui échappe à la présidence tournante.",u:["https://fr.wikipedia.org/wiki/Conseil_de_l%27Union_europ%C3%A9enne"],s:"TUE, art. 18"},
{id:"ue2-140",t:"ue",q:"Que désigne le « trio » de présidences du Conseil de l'UE ?",o:["Trois États qui se succèdent à la présidence et suivent un programme commun sur 18 mois","Les trois plus gros contributeurs au budget","Le Parlement, le Conseil et la Commission en négociation","Les trois derniers États ayant adhéré"],a:0,e:"La négociation à trois institutions s'appelle, elle, le « trilogue ».",u:["https://fr.wikipedia.org/wiki/Pr%C3%A9sidence_du_Conseil_de_l%27Union_europ%C3%A9enne"],s:"Banque UE"},
{id:"ue2-141",t:"ue",q:"Quels États forment le trio de présidences du Conseil de l'UE de juillet 2026 à décembre 2027 ?",o:["La Pologne, le Danemark et Chypre","L'Espagne, la Belgique et la Hongrie","La France, la Tchéquie et la Suède","L'Irlande, la Lituanie et la Grèce"],a:3,e:"Irlande au second semestre 2026, Lituanie au premier semestre 2027, Grèce au second semestre 2027.",u:["https://fr.wikipedia.org/wiki/Pr%C3%A9sidence_du_Conseil_de_l%27Union_europ%C3%A9enne"],s:"Fiche 8",act:1},
{id:"ue2-142",t:"ue",q:"Quand la France a-t-elle exercé pour la dernière fois la présidence du Conseil de l'UE ?",o:["Second semestre 2008","Premier semestre 2022","Second semestre 2024","Premier semestre 2026"],a:1,e:"De janvier à juin 2022 ; la précédente datait du second semestre 2008.",u:["https://fr.wikipedia.org/wiki/Pr%C3%A9sidence_du_Conseil_de_l%27Union_europ%C3%A9enne"],s:"Banque UE"},
{id:"ue2-143",t:"ue",q:"Que désigne le Coreper ?",o:["Le Comité européen des régions","Le comité des représentants permanents des États membres","La conférence des présidents du Parlement européen","Le collège des commissaires"],a:1,e:"Il prépare les travaux du Conseil de l'UE (art. 16, paragraphe 7, TUE et art. 240 TFUE).",u:["https://fr.wikipedia.org/wiki/Comit%C3%A9_des_repr%C3%A9sentants_permanents_(Union_europ%C3%A9enne)"],s:"TFUE, art. 240"},
{id:"ue2-144",t:"ue",q:"Quelle formation du Coreper réunit les ambassadeurs, représentants permanents des États membres ?",o:["Le Coreper I","Le Comité spécial agriculture","Le Coreper II","Le Comité politique et de sécurité"],a:2,e:"Le Coreper II prépare notamment les Conseils Affaires générales, Affaires étrangères, ECOFIN et JAI ; le Coreper I réunit les représentants permanents adjoints.",u:["https://fr.wikipedia.org/wiki/Comit%C3%A9_des_repr%C3%A9sentants_permanents_(Union_europ%C3%A9enne)"],s:"Banque UE"},
{id:"ue2-145",t:"ue",q:"Au Conseil de l'UE, que sont les « points A » de l'ordre du jour ?",o:["Des points déjà accordés au Coreper, adoptés sans débat","Des points soumis à l'unanimité","Des points réservés aux affaires étrangères","Des points inscrits à la demande du Parlement européen"],a:0,e:"Les « points B » font, eux, l'objet d'une discussion entre ministres.",u:["https://fr.wikipedia.org/wiki/Comit%C3%A9_des_repr%C3%A9sentants_permanents_(Union_europ%C3%A9enne)"],s:"Banque UE"},
{id:"ue2-146",t:"ue",q:"Sauf disposition contraire des traités, comment le Conseil de l'UE statue-t-il ?",o:["À l'unanimité","À la majorité qualifiée","À la majorité simple","Par consensus"],a:1,e:"Art. 16, paragraphe 3, TUE ; l'unanimité reste requise notamment pour la fiscalité, la PESC et l'adhésion.",u:["https://fr.wikipedia.org/wiki/Majorit%C3%A9_qualifi%C3%A9e"],s:"TUE, art. 16"},
{id:"ue2-147",t:"ue",q:"Avec 27 États membres, combien d'États faut-il au minimum pour atteindre le seuil de 55 % de la majorité qualifiée ?",o:["14","15","16","18"],a:1,e:"55 % de 27 = 14,85, arrondi à 15 États ; ils doivent aussi représenter au moins 65 % de la population.",u:["https://fr.wikipedia.org/wiki/Majorit%C3%A9_qualifi%C3%A9e"],s:"TUE, art. 16"},
{id:"ue2-148",t:"ue",q:"Quelle majorité qualifiée s'applique lorsque le Conseil ne statue pas sur proposition de la Commission ou du haut représentant ?",o:["55 % des États membres représentant au moins 65 % de la population","Les deux tiers des États membres","50 % des États membres représentant 50 % de la population","72 % des États membres représentant au moins 65 % de la population"],a:3,e:"Majorité qualifiée « renforcée » de l'article 238, paragraphe 2, TFUE.",u:["https://fr.wikipedia.org/wiki/Majorit%C3%A9_qualifi%C3%A9e"],s:"TFUE, art. 238"},
{id:"ue2-149",t:"ue",q:"Au Conseil de l'UE, l'abstention d'un État empêche-t-elle l'adoption d'une décision requérant l'unanimité ?",o:["Oui, elle équivaut à un vote contre","Oui, sauf en matière fiscale","Non, l'abstention ne fait pas obstacle à l'unanimité","Oui, sauf si l'État qui s'abstient exerce la présidence"],a:2,e:"Art. 238, paragraphe 4, TFUE.",u:["https://fr.wikipedia.org/wiki/Conseil_de_l%27Union_europ%C3%A9enne"],s:"TFUE, art. 238"},
{id:"ue2-150",t:"ue",q:"En PESC, comment s'appelle le mécanisme qui permet à un État de ne pas bloquer une décision unanime sans être tenu de l'appliquer ?",o:["Le compromis de Luxembourg","La clause passerelle","Le carton jaune","L'abstention constructive"],a:3,e:"Art. 31 TUE : l'État fait une déclaration formelle et accepte que la décision engage l'Union.",u:["https://fr.wikipedia.org/wiki/Abstention_constructive"],s:"TUE, art. 31"},
{id:"ue2-151",t:"ue",q:"Comment le Conseil adopte-t-il les directives d'harmonisation des taxes sur le chiffre d'affaires (TVA) et des accises ?",o:["À la majorité qualifiée, en codécision avec le Parlement","À la majorité simple","À l'unanimité, après consultation du Parlement européen","Par délégation à la Commission"],a:2,e:"Art. 113 TFUE : procédure législative spéciale.",u:["https://fr.wikipedia.org/wiki/Proc%C3%A9dure_l%C3%A9gislative_ordinaire"],s:"TFUE, art. 113"},
{id:"ue2-152",t:"ue",q:"Les délibérations du Conseil de l'UE sur un projet d'acte législatif sont-elles publiques ?",o:["Non, ses délibérations restent toujours confidentielles","Oui, il siège en public lorsqu'il délibère et vote sur un projet d'acte législatif","Seulement lorsqu'il statue en matière de PESC","Seulement si le Parlement européen le demande"],a:1,e:"Art. 16, paragraphe 8, TUE : chaque session est divisée en une partie législative publique et une partie non législative.",u:["https://fr.wikipedia.org/wiki/Conseil_de_l%27Union_europ%C3%A9enne"],s:"TUE, art. 16"},
{id:"ue2-153",t:"ue",q:"Quelle est la nature de l'Eurogroupe ?",o:["Une réunion informelle des ministres des Finances des États de la zone euro","Une formation officielle du Conseil réunissant les 27 ministres des Finances","Un organe de la BCE","Une direction de la Commission"],a:0,e:"Protocole n° 14 annexé aux traités ; les décisions formelles sont prises par le Conseil ECOFIN.",u:["https://fr.wikipedia.org/wiki/Eurogroupe"],s:"Protocole n° 14"},
// --- Commission européenne ---
{id:"ue2-154",t:"ue",q:"Quelle est la durée du mandat de la Commission européenne ?",o:["2 ans et demi","4 ans","5 ans","6 ans"],a:2,e:"Il coïncide avec la législature du Parlement européen ; la Commission actuelle est entrée en fonction le 1er décembre 2024.",u:["https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/european-commission_fr"],s:"TUE, art. 17"},
{id:"ue2-155",t:"ue",q:"Le traité de Lisbonne prévoyait de réduire le nombre de commissaires à partir de 2014. Qu'a-t-il été décidé ?",o:["Une réduction aux deux tiers du nombre d'États","Le maintien d'un commissaire par État membre, par décision du Conseil européen","Un commissaire pour deux États","Une Commission de quinze membres"],a:1,e:"Garantie donnée à l'Irlande en 2008 pour la ratification de Lisbonne, mise en œuvre en 2013.",u:["https://fr.wikipedia.org/wiki/Commission_europ%C3%A9enne"],s:"TUE, art. 17"},
{id:"ue2-156",t:"ue",q:"Avant le vote d'approbation du collège, comment les commissaires désignés sont-ils évalués par le Parlement européen ?",o:["Par des auditions devant les commissions parlementaires compétentes","Par un concours organisé par l'EPSO","Par un vote individuel en séance plénière sur chaque commissaire","Par un avis de la Cour de justice"],a:0,e:"La plénière vote ensuite sur le collège dans son ensemble, président et haut représentant compris.",u:["https://fr.wikipedia.org/wiki/Commission_europ%C3%A9enne"],s:"TUE, art. 17"},
{id:"ue2-157",t:"ue",q:"Après le vote d'approbation du Parlement européen, qui nomme la Commission ?",o:["Le Conseil de l'UE, à l'unanimité","Le président du Parlement européen","Le Conseil européen, à la majorité qualifiée","La Cour de justice de l'Union"],a:2,e:"Art. 17, paragraphe 7, TUE.",u:["https://fr.wikipedia.org/wiki/Commission_europ%C3%A9enne"],s:"TUE, art. 17"},
{id:"ue2-158",t:"ue",q:"Quelle candidate française au poste de commissaire a été rejetée par le Parlement européen en 2019 ?",o:["Nathalie Loiseau","Laurence Boone","Agnès Pannier-Runacher","Sylvie Goulard"],a:3,e:"Après son rejet en commission, la France a proposé Thierry Breton.",u:["https://fr.wikipedia.org/wiki/Sylvie_Goulard"],s:"Banque UE"},
{id:"ue2-159",t:"ue",q:"Quelle Commission a démissionné collectivement en mars 1999, avant le vote d'une motion de censure ?",o:["La Commission Delors","La Commission Prodi","La Commission Santer","La Commission Barroso"],a:2,e:"À la suite d'un rapport d'experts sur la fraude et la mauvaise gestion ; l'OLAF est créé la même année.",u:["https://fr.wikipedia.org/wiki/Commission_Santer"],s:"Banque UE"},
{id:"ue2-160",t:"ue",q:"En cas d'adoption d'une motion de censure par le Parlement européen, qui doit démissionner ?",o:["Le seul président de la Commission","Le seul commissaire visé par la motion","Le président du Conseil européen","L'ensemble du collège des commissaires"],a:3,e:"Art. 17, paragraphe 8, TUE et art. 234 TFUE : la censure vise le collège entier ; le haut représentant quitte alors ses fonctions au sein de la Commission.",u:["https://fr.wikipedia.org/wiki/Commission_europ%C3%A9enne"],s:"TFUE, art. 234"},
{id:"ue2-161",t:"ue",q:"Qui peut demander à un commissaire de démissionner, l'obligeant à quitter ses fonctions ?",o:["Le président du Parlement européen","Le président de la Commission","Le Conseil européen seul","Le gouvernement de l'État dont il est ressortissant"],a:1,e:"Art. 17, paragraphe 6, TUE.",u:["https://fr.wikipedia.org/wiki/Commission_europ%C3%A9enne"],s:"TUE, art. 17"},
{id:"ue2-162",t:"ue",q:"Les commissaires européens peuvent-ils recevoir des instructions de leur gouvernement ?",o:["Non, ils exercent leurs fonctions en pleine indépendance","Oui, ils représentent leur État","Oui, en matière budgétaire","Oui, si le Conseil européen l'autorise"],a:0,e:"Art. 17, paragraphe 3, TUE : ils ne sollicitent ni n'acceptent d'instructions d'aucun gouvernement.",u:["https://fr.wikipedia.org/wiki/Commission_europ%C3%A9enne"],s:"TUE, art. 17"},
{id:"ue2-163",t:"ue",q:"Qui négocie les accords commerciaux de l'Union avec les pays tiers ?",o:["Chaque État membre séparément","Le Parlement européen","La Commission, sur mandat du Conseil","Le Conseil européen"],a:2,e:"Art. 207 et 218 TFUE ; l'accord est conclu par le Conseil, en général après approbation du Parlement.",u:["https://fr.wikipedia.org/wiki/Commission_europ%C3%A9enne"],s:"TFUE, art. 207"},
{id:"ue2-164",t:"ue",q:"Comment appelle-t-on les actes non législatifs par lesquels la Commission complète ou modifie des éléments non essentiels d'un acte législatif ?",o:["Les actes d'exécution","Les directives","Les avis","Les actes délégués"],a:3,e:"Art. 290 TFUE. Les actes d'exécution (art. 291) assurent des conditions uniformes d'application.",u:["https://fr.wikipedia.org/wiki/Comitologie"],s:"TFUE, art. 290"},
{id:"ue2-165",t:"ue",q:"Quelle direction générale de la Commission est chargée de la fiscalité et de l'union douanière ?",o:["La DG ECFIN","La DG TAXUD","La DG COMP","La DG BUDG"],a:1,e:"ECFIN : affaires économiques et financières ; COMP : concurrence ; BUDG : budget.",u:["https://fr.wikipedia.org/wiki/Direction_g%C3%A9n%C3%A9rale_de_la_Fiscalit%C3%A9_et_de_l%27Union_douani%C3%A8re"],s:"Banque UE"},
{id:"ue2-166",t:"ue",q:"Quel bâtiment de Bruxelles abrite le siège de la Commission européenne ?",o:["Le Berlaymont","Le bâtiment Louise-Weiss","Le bâtiment Europa","Le bâtiment Paul-Henri-Spaak"],a:0,e:"Le bâtiment Paul-Henri-Spaak accueille le Parlement à Bruxelles.",u:["https://fr.wikipedia.org/wiki/B%C3%A2timent_Berlaymont"],s:"Banque UE"},
// --- Cour de justice de l'Union européenne ---
{id:"ue2-167",t:"ue",q:"Combien d'avocats généraux assistent la Cour de justice ?",o:["8","11","15","27"],a:1,e:"Ils sont onze depuis 2015.",u:["https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/court-justice-european-union-cjeu_fr"],s:"Banque UE"},
{id:"ue2-168",t:"ue",q:"Dans une Union à 27 États, combien de juges le statut de la Cour prévoit-il pour le Tribunal de l'Union européenne ?",o:["27","47","54","81"],a:2,e:"Deux juges par État membre (art. 48 du statut), selon la réforme de 2015 mise en œuvre par étapes jusqu'en 2019.",u:["https://fr.wikipedia.org/wiki/Tribunal_de_l%27Union_europ%C3%A9enne"],s:"Banque UE"},
{id:"ue2-169",t:"ue",q:"Quelle est la durée du mandat des juges de la Cour de justice de l'Union ?",o:["3 ans","6 ans renouvelables","9 ans non renouvelables","À vie"],a:1,e:"Renouvellement partiel tous les trois ans ; le président est élu par les juges pour trois ans.",u:["https://fr.wikipedia.org/wiki/Cour_de_justice_de_l%27Union_europ%C3%A9enne"],s:"TFUE, art. 253"},
{id:"ue2-170",t:"ue",q:"Comment les juges de la Cour de justice de l'Union sont-ils nommés ?",o:["Par le Parlement européen, après audition","Par la Commission, sur proposition des États","D'un commun accord par les gouvernements des États membres, après avis d'un comité","Par le Conseil européen, à la majorité simple"],a:2,e:"Le comité de l'article 255 TFUE apprécie l'aptitude des candidats.",u:["https://fr.wikipedia.org/wiki/Cour_de_justice_de_l%27Union_europ%C3%A9enne"],s:"TFUE, art. 253"},
{id:"ue2-171",t:"ue",q:"Depuis le 1er octobre 2024, quelle juridiction traite les questions préjudicielles relatives notamment au système commun de TVA et aux accises ?",o:["Le Tribunal de l'Union européenne","Le Conseil d'État","La Cour des comptes européenne","La Cour européenne des droits de l'homme"],a:0,e:"La Cour de justice lui transfère les renvois dans six matières : TVA, accises, code des douanes, classement tarifaire, droits des passagers, quotas d'émission.",u:["https://fr.wikipedia.org/wiki/Tribunal_de_l%27Union_europ%C3%A9enne"],s:"Banque UE"},
{id:"ue2-172",t:"ue",q:"Dans quel délai un recours en annulation doit-il être formé devant la juridiction de l'Union ?",o:["15 jours","2 mois","6 mois","1 an"],a:1,e:"À compter de la publication ou de la notification de l'acte (art. 263 TFUE).",u:["https://fr.wikipedia.org/wiki/Recours_en_annulation_en_droit_de_l%27Union_europ%C3%A9enne"],s:"TFUE, art. 263"},
{id:"ue2-173",t:"ue",q:"Quel recours sanctionne l'abstention illégale d'une institution de l'Union de statuer ?",o:["Le recours en manquement","Le recours en annulation","Le renvoi préjudiciel","Le recours en carence"],a:3,e:"Art. 265 TFUE ; l'institution doit avoir été préalablement invitée à agir.",u:["https://fr.wikipedia.org/wiki/Recours_en_carence"],s:"TFUE, art. 265"},
{id:"ue2-174",t:"ue",q:"Que peut infliger la Cour de justice à un État qui n'exécute pas un premier arrêt en manquement ?",o:["La suspension de son droit de vote au Conseil","Une somme forfaitaire et/ou une astreinte","L'exclusion de l'Union","Une peine d'emprisonnement pour ses ministres"],a:1,e:"Art. 260 TFUE, sur saisine de la Commission. La suspension de droits relève de l'article 7 TUE.",u:["https://fr.wikipedia.org/wiki/Recours_en_manquement"],s:"TFUE, art. 260"},
{id:"ue2-175",t:"ue",q:"Quand une juridiction nationale est-elle en principe tenue de saisir la Cour de justice d'une question préjudicielle ?",o:["Dans tous les litiges où le droit de l'Union est invoqué","Lorsque ses décisions ne sont pas susceptibles d'un recours juridictionnel de droit interne","Jamais, ce n'est qu'une faculté","Seulement à la demande de la Commission"],a:1,e:"Art. 267 TFUE : obligation pour les juridictions suprêmes, comme le Conseil d'État ou la Cour de cassation, sauf exceptions (jurisprudence Cilfit).",u:["https://fr.wikipedia.org/wiki/Question_pr%C3%A9judicielle"],s:"TFUE, art. 267"},
{id:"ue2-176",t:"ue",q:"Quel est le rôle d'un avocat général à la Cour de justice de l'Union ?",o:["Représenter la Commission et défendre l'intérêt de l'Union devant la Cour","Défendre l'État membre mis en cause dans un recours en manquement","Instruire les plaintes des citoyens contre les institutions de l'Union","Présenter en toute impartialité des conclusions motivées, que la Cour n'est pas tenue de suivre"],a:3,e:"Art. 252 TFUE ; ses conclusions sont publiées avant l'arrêt.",u:["https://fr.wikipedia.org/wiki/Cour_de_justice_de_l%27Union_europ%C3%A9enne"],s:"TFUE, art. 252"},
{id:"ue2-177",t:"ue",q:"Contre une décision du Tribunal de l'Union européenne, quel recours est possible ?",o:["Un pourvoi devant la Cour de justice, limité aux questions de droit","Un appel devant la Cour européenne des droits de l'homme","Un recours devant le Conseil d'État","Aucun recours"],a:0,e:"Art. 256 TFUE ; certains pourvois font l'objet d'une admission préalable.",u:["https://fr.wikipedia.org/wiki/Tribunal_de_l%27Union_europ%C3%A9enne"],s:"TFUE, art. 256"},
{id:"ue2-178",t:"ue",q:"Quelle est la langue de délibéré de la Cour de justice de l'Union européenne ?",o:["L'anglais","L'allemand","Le français","La langue de l'affaire"],a:2,e:"Les arrêts sont rendus dans la langue de procédure, mais les juges délibèrent en français, sans interprète.",u:["https://fr.wikipedia.org/wiki/Cour_de_justice_de_l%27Union_europ%C3%A9enne"],s:"Banque UE"},
{id:"ue2-179",t:"ue",q:"Quel principe l'arrêt « Cassis de Dijon » (1979) a-t-il consacré ?",o:["La reconnaissance mutuelle des produits légalement commercialisés dans un autre État membre","La primauté du droit communautaire","La responsabilité de l'État pour violation du droit communautaire","L'effet direct des règlements"],a:0,e:"Un produit légalement fabriqué et vendu dans un État doit en principe être admis dans les autres, sauf exigence impérative d'intérêt général.",u:["https://fr.wikipedia.org/wiki/Arr%C3%AAt_Cassis_de_Dijon"],s:"Banque UE"},
{id:"ue2-180",t:"ue",q:"Quel arrêt de 1991 consacre la responsabilité d'un État envers les particuliers pour non-transposition d'une directive ?",o:["Van Gend en Loos","Francovich","Cassis de Dijon","Simmenthal"],a:1,e:"Arrêt Francovich et Bonifaci contre Italie du 19 novembre 1991.",u:["https://fr.wikipedia.org/wiki/Cour_de_justice_de_l%27Union_europ%C3%A9enne"],s:"Banque UE"},
{id:"ue2-181",t:"ue",q:"Selon l'arrêt Simmenthal (1978), que doit faire le juge national face à une loi nationale contraire au droit communautaire ?",o:["Surseoir à statuer jusqu'à l'abrogation de la loi","Saisir le parlement national","La laisser inappliquée, sans attendre son abrogation","Appliquer la loi si elle est postérieure"],a:2,e:"Conséquence de la primauté posée par l'arrêt Costa contre ENEL (1964).",u:["https://fr.wikipedia.org/wiki/Arr%C3%AAt_Simmenthal"],s:"Banque UE"},
// --- Banque centrale européenne ---
{id:"ue2-182",t:"ue",q:"Combien de membres compte le directoire de la BCE ?",o:["4","6","12","27"],a:1,e:"Le président, le vice-président et quatre autres membres.",u:["https://fr.wikipedia.org/wiki/Banque_centrale_europ%C3%A9enne"],s:"TFUE, art. 283"},
{id:"ue2-183",t:"ue",q:"Qui nomme les membres du directoire de la BCE ?",o:["Le Parlement européen","Les gouverneurs des banques centrales nationales","La Commission européenne","Le Conseil européen, à la majorité qualifiée"],a:3,e:"Sur recommandation du Conseil, après consultation du Parlement et du conseil des gouverneurs, pour huit ans non renouvelables.",u:["https://fr.wikipedia.org/wiki/Banque_centrale_europ%C3%A9enne"],s:"TFUE, art. 283"},
{id:"ue2-184",t:"ue",q:"Qui compose le conseil des gouverneurs de la BCE ?",o:["Les ministres des Finances de la zone euro","Les gouverneurs des banques centrales des 27 États membres","Les commissaires chargés de l'économie","Les membres du directoire et les gouverneurs des banques centrales nationales de la zone euro"],a:3,e:"C'est l'organe de décision de la politique monétaire ; les droits de vote des gouverneurs tournent depuis 2015.",u:["https://www.ecb.europa.eu/ecb/decisions/govc/html/index.fr.html"],s:"TFUE, art. 283"},
{id:"ue2-185",t:"ue",q:"Combien de membres compte le conseil des gouverneurs de la BCE en 2026 ?",o:["21","26","27","33"],a:2,e:"Les 6 membres du directoire et les 21 gouverneurs des banques centrales de la zone euro, depuis l'entrée de la Bulgarie.",u:["https://www.ecb.europa.eu/ecb/decisions/govc/html/index.fr.html"],s:"Banque UE",act:1},
{id:"ue2-186",t:"ue",q:"Qu'est-ce que l'Eurosystème ?",o:["La BCE et les banques centrales des 27 États membres","Le réseau des trésors publics de la zone euro","La BCE et les banques centrales nationales des États de la zone euro","L'ensemble des banques commerciales de la zone euro"],a:2,e:"La BCE et les banques centrales des 27 États forment le Système européen de banques centrales (SEBC).",u:["https://www.ecb.europa.eu/ecb/orga/escb/html/index.fr.html"],s:"Banque UE"},
{id:"ue2-187",t:"ue",q:"Que regroupe le Système européen de banques centrales (SEBC) ?",o:["La BCE et les seules banques centrales de la zone euro","La BCE et les banques centrales nationales de tous les États membres de l'Union","Les banques centrales nationales, sans la BCE","La BCE, la BEI et le Mécanisme européen de stabilité"],a:1,e:"Art. 282 TFUE. L'Eurosystème n'en comprend que la partie zone euro.",u:["https://www.ecb.europa.eu/ecb/orga/escb/html/index.fr.html"],s:"TFUE, art. 282"},
{id:"ue2-188",t:"ue",q:"Quel organe de la BCE associe les gouverneurs des banques centrales des États membres qui n'ont pas adopté l'euro ?",o:["Le conseil général","Le directoire","Le conseil des gouverneurs","Le comité d'audit"],a:0,e:"Composé du président, du vice-président et des gouverneurs des 27 banques centrales ; il disparaîtra quand tous auront adopté l'euro.",u:["https://fr.wikipedia.org/wiki/Banque_centrale_europ%C3%A9enne"],s:"Banque UE"},
{id:"ue2-189",t:"ue",q:"Quelle règle interdit à la BCE et aux banques centrales nationales d'accorder des crédits aux États ou d'acheter directement leurs titres de dette ?",o:["Le principe de subsidiarité (art. 5 TUE)","La clause de non-renflouement (art. 125 TFUE)","Le principe de proportionnalité (art. 5 TUE)","L'interdiction du financement monétaire (art. 123 TFUE)"],a:3,e:"La clause de non-renflouement interdit, elle, à l'Union et aux États de prendre en charge les engagements d'un autre État.",u:["https://fr.wikipedia.org/wiki/Banque_centrale_europ%C3%A9enne"],s:"TFUE, art. 123"},
{id:"ue2-190",t:"ue",q:"Qui détient le droit exclusif d'autoriser l'émission des billets en euros ?",o:["La BCE","La Commission européenne","Le Conseil ECOFIN","L'Eurogroupe"],a:0,e:"Art. 128 TFUE. Les pièces sont émises par les États, dans un volume approuvé par la BCE.",u:["https://fr.wikipedia.org/wiki/Banque_centrale_europ%C3%A9enne"],s:"TFUE, art. 128"},
{id:"ue2-191",t:"ue",q:"Quel Français a présidé la BCE de 2003 à 2011 ?",o:["Christian Noyer","Jean-Claude Trichet","Jacques de Larosière","François Villeroy de Galhau"],a:1,e:"Ancien gouverneur de la Banque de France ; Christian Noyer a été vice-président de la BCE de 1998 à 2002.",u:["https://fr.wikipedia.org/wiki/Jean-Claude_Trichet"],s:"Banque UE"},
{id:"ue2-192",t:"ue",q:"Quelle fonction Christine Lagarde occupait-elle juste avant de présider la BCE ?",o:["Présidente de la Banque mondiale","Commissaire européenne","Directrice générale du FMI","Gouverneure de la Banque de France"],a:2,e:"De 2011 à 2019 ; elle avait été ministre de l'Économie de 2007 à 2011.",u:["https://fr.wikipedia.org/wiki/Christine_Lagarde"],s:"Banque UE"},
{id:"ue2-193",t:"ue",q:"Depuis novembre 2014, quel mécanisme confie à la BCE la supervision directe des grandes banques de la zone euro ?",o:["Le mécanisme de surveillance unique (MSU)","Le Mécanisme européen de stabilité (MES)","Le mécanisme de change européen (MCE II)","Le Conseil de résolution unique (CRU)"],a:0,e:"Premier pilier de l'union bancaire, complété par le mécanisme de résolution unique.",u:["https://fr.wikipedia.org/wiki/M%C3%A9canisme_de_surveillance_unique"],s:"Banque UE"},
// --- Cour des comptes européenne ---
{id:"ue2-194",t:"ue",q:"Comment les membres de la Cour des comptes européenne sont-ils nommés ?",o:["Par le Parlement européen seul, pour cinq ans","Par la Commission, pour quatre ans","Par les cours des comptes nationales, à vie","Par le Conseil, après consultation du Parlement européen, pour six ans renouvelables"],a:3,e:"Art. 286 TFUE ; ils élisent leur président pour trois ans.",u:["https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/european-court-auditors-eca_fr"],s:"TFUE, art. 286"},
{id:"ue2-195",t:"ue",q:"Quel document la Cour des comptes européenne fournit-elle chaque année au Parlement et au Conseil sur la fiabilité des comptes et la régularité des opérations ?",o:["Un avis conforme","Une déclaration d'assurance (DAS)","Des recommandations par pays","Un rapport de convergence"],a:1,e:"Prévue depuis Maastricht, elle accompagne le rapport annuel et éclaire la décharge budgétaire.",u:["https://fr.wikipedia.org/wiki/Cour_des_comptes_europ%C3%A9enne"],s:"TFUE, art. 287"},
{id:"ue2-196",t:"ue",q:"La Cour des comptes européenne peut-elle sanctionner elle-même les fraudes qu'elle détecte ?",o:["Oui, elle inflige des amendes aux fraudeurs","Oui, elle juge les comptables publics de l'Union","Non, elle n'a pas de pouvoir juridictionnel","Oui, elle peut suspendre les fonds versés à un État"],a:2,e:"Contrairement à la Cour des comptes française, elle n'est pas une juridiction : elle signale les fraudes présumées, notamment à l'OLAF.",u:["https://fr.wikipedia.org/wiki/Cour_des_comptes_europ%C3%A9enne"],s:"Banque UE"},
// --- Organes consultatifs, Médiateur, BEI et services ---
{id:"ue2-197",t:"ue",q:"Quels sont les trois groupes du Comité économique et social européen ?",o:["Gauche, centre, droite","Régions, villes, États","Employeurs, travailleurs, organisations de la société civile","Agriculteurs, industriels, commerçants"],a:2,e:"Il représente les partenaires sociaux et la société civile organisée.",u:["https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/european-economic-and-social-committee-eesc_fr"],s:"Banque UE"},
{id:"ue2-198",t:"ue",q:"Combien de membres la France compte-t-elle au Comité européen des régions ?",o:["9","18","24","81"],a:2,e:"Comme l'Allemagne et l'Italie ; la France a aussi 24 membres au CESE.",u:["https://fr.wikipedia.org/wiki/Comit%C3%A9_europ%C3%A9en_des_r%C3%A9gions"],s:"Banque UE"},
{id:"ue2-199",t:"ue",q:"Quelle condition doivent remplir les membres du Comité européen des régions ?",o:["Être fonctionnaires d'une administration déconcentrée de l'État","Être titulaires d'un mandat électoral régional ou local, ou politiquement responsables devant une assemblée élue","Être membres d'un parlement national","Être désignés par les partis politiques européens"],a:1,e:"Art. 300 et 305 TFUE ; ils sont nommés pour cinq ans par le Conseil sur proposition des États.",u:["https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/european-committee-regions-cor_fr"],s:"TFUE, art. 300"},
{id:"ue2-200",t:"ue",q:"Quelle faculté le traité de Lisbonne a-t-il reconnue au Comité européen des régions ?",o:["Saisir la Cour de justice pour violation du principe de subsidiarité","Voter les actes législatifs","Censurer la Commission","Nommer les commissaires"],a:0,e:"Pour les actes sur lesquels sa consultation est obligatoire (protocole n° 2).",u:["https://fr.wikipedia.org/wiki/Comit%C3%A9_europ%C3%A9en_des_r%C3%A9gions"],s:"Protocole n° 2"},
{id:"ue2-201",t:"ue",q:"Qui élit le Médiateur européen ?",o:["Le Conseil européen","La Commission européenne","Les citoyens, par un vote en ligne","Le Parlement européen"],a:3,e:"Élu après chaque élection européenne pour la durée de la législature ; il siège à Strasbourg.",u:["https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/european-ombudsman_fr"],s:"TFUE, art. 228"},
{id:"ue2-202",t:"ue",q:"Le Médiateur européen peut-il instruire une plainte contre une administration fiscale nationale ?",o:["Non, il ne traite que la mauvaise administration des organes de l'Union","Oui, pour toute administration d'un État membre","Oui, si la plainte concerne la TVA","Oui, si le médiateur national l'y autorise"],a:0,e:"Les plaintes contre une administration nationale relèvent des médiateurs nationaux (en France, le Défenseur des droits).",u:["https://fr.wikipedia.org/wiki/M%C3%A9diateur_europ%C3%A9en"],s:"TFUE, art. 228"},
{id:"ue2-203",t:"ue",q:"Où siège la Banque européenne d'investissement ?",o:["À Francfort","À Luxembourg","À Bruxelles","À Strasbourg"],a:1,e:"Elle finance des projets conformes aux objectifs de l'Union, en empruntant sur les marchés.",u:["https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/european-investment-bank-eib_fr"],s:"Banque UE"},
{id:"ue2-204",t:"ue",q:"Quelle autorité veille au respect de la protection des données personnelles par les institutions et organes de l'Union ?",o:["La CNIL","Le Médiateur européen","L'Agence de l'UE pour la cybersécurité","Le Contrôleur européen de la protection des données"],a:3,e:"Les autorités nationales (CNIL en France) contrôlent, elles, les traitements relevant de leur État.",u:["https://fr.wikipedia.org/wiki/Contr%C3%B4leur_europ%C3%A9en_de_la_protection_des_donn%C3%A9es"],s:"Banque UE"},
// --- Agences et organismes : sièges ---
{id:"ue2-205",t:"ue",q:"Dans quelle ville siège Europol ?",o:["Lyon","Bruxelles","La Haye","Varsovie"],a:2,e:"Agence de coopération policière ; Lyon accueille Interpol, Varsovie Frontex.",u:["https://fr.wikipedia.org/wiki/Europol"],s:"Banque UE"},
{id:"ue2-206",t:"ue",q:"Quelle agence de l'Union, installée à La Haye, coordonne la coopération judiciaire pénale entre les autorités nationales ?",o:["Europol","Frontex","Eurojust","Le CEPOL"],a:2,e:"Eurojust réunit des magistrats détachés par chaque État ; Europol est une agence de police.",u:["https://fr.wikipedia.org/wiki/Eurojust"],s:"Banque UE"},
{id:"ue2-207",t:"ue",q:"Sous quel nom officiel Frontex est-elle désignée depuis 2016 ?",o:["Agence européenne de défense","Agence européenne de garde-frontières et de garde-côtes","Agence de l'Union européenne pour l'asile","Office européen de police"],a:1,e:"Créée en 2004, elle dispose désormais d'un corps permanent de garde-frontières ; siège à Varsovie.",u:["https://fr.wikipedia.org/wiki/Agence_europ%C3%A9enne_de_garde-fronti%C3%A8res_et_de_garde-c%C3%B4tes"],s:"Banque UE"},
{id:"ue2-208",t:"ue",q:"Dans quelle ville l'Agence européenne des médicaments s'est-elle installée après le Brexit ?",o:["Amsterdam","Lille","Milan","Bratislava"],a:0,e:"Elle a quitté Londres en 2019 ; Lille, Milan et Bratislava étaient candidates.",u:["https://fr.wikipedia.org/wiki/Agence_europ%C3%A9enne_des_m%C3%A9dicaments"],s:"Banque UE"},
{id:"ue2-209",t:"ue",q:"Quelle autorité de l'Union a quitté Londres pour Paris en 2019 ?",o:["L'Agence européenne des médicaments","L'Autorité européenne des marchés financiers","L'Autorité européenne des assurances et des pensions professionnelles","L'Autorité bancaire européenne"],a:3,e:"L'Autorité européenne des marchés financiers est à Paris depuis sa création en 2011 ; l'autorité des assurances est à Francfort.",u:["https://fr.wikipedia.org/wiki/Autorit%C3%A9_bancaire_europ%C3%A9enne"],s:"Banque UE"},
{id:"ue2-210",t:"ue",q:"Où siège l'Autorité européenne des marchés financiers (ESMA) ?",o:["Francfort","Londres","Luxembourg","Paris"],a:3,e:"Avec l'Autorité bancaire européenne (Paris) et l'autorité des assurances (Francfort), elle forme les autorités européennes de surveillance.",u:["https://fr.wikipedia.org/wiki/Autorit%C3%A9_europ%C3%A9enne_des_march%C3%A9s_financiers"],s:"Banque UE"},
{id:"ue2-211",t:"ue",q:"Où siège l'Autorité européenne des assurances et des pensions professionnelles (EIOPA) ?",o:["Francfort","Paris","Dublin","Bruxelles"],a:0,e:"Créée en 2011, comme l'Autorité bancaire européenne et l'ESMA.",u:["https://fr.wikipedia.org/wiki/Autorit%C3%A9_europ%C3%A9enne_des_assurances_et_des_pensions_professionnelles"],s:"Banque UE"},
{id:"ue2-212",t:"ue",q:"Quelle ville a été choisie en 2024 pour accueillir l'Autorité européenne de lutte contre le blanchiment de capitaux (AMLA) ?",o:["Paris","Francfort","Rome","Madrid"],a:1,e:"Choix de février 2024 ; Paris, Rome et Madrid faisaient partie des villes candidates.",u:["https://www.amla.europa.eu/index_en"],s:"Banque UE"},
{id:"ue2-213",t:"ue",q:"Selon quelle modalité le Parquet européen a-t-il été institué ?",o:["Par une décision unanime des 27 États","Par un traité intergouvernemental hors de l'Union","Par une coopération renforcée entre une partie des États membres","Par une directive transposée par tous les États"],a:2,e:"Règlement de 2017, sur le fondement de l'article 86 TFUE ; il est opérationnel depuis le 1er juin 2021.",u:["https://fr.wikipedia.org/wiki/Parquet_europ%C3%A9en"],s:"TFUE, art. 86"},
{id:"ue2-214",t:"ue",q:"Quelles infractions relèvent de la compétence du Parquet européen ?",o:["Les actes de terrorisme visant plusieurs États membres","Les atteintes aux intérêts financiers de l'Union, dont certaines fraudes transfrontières à la TVA","Les trafics de stupéfiants transfrontières","Toutes les fraudes fiscales nationales"],a:1,e:"Pour la TVA, la fraude doit concerner au moins deux États et un préjudice d'au moins 10 M€. Il recherche, poursuit et renvoie en jugement devant les juridictions nationales.",u:["https://european-union.europa.eu/institutions-law-budget/institutions-and-bodies/search-all-eu-institutions-and-bodies/european-public-prosecutors-office-eppo_fr"],s:"Banque UE"},
{id:"ue2-215",t:"ue",q:"Quelle est la différence entre l'OLAF et le Parquet européen ?",o:["L'OLAF exerce des poursuites pénales, le Parquet européen mène des enquêtes administratives","Les deux sont des juridictions de jugement","L'OLAF relève du Conseil de l'Europe","L'OLAF mène des enquêtes administratives, le Parquet européen exerce des poursuites pénales"],a:3,e:"L'OLAF transmet au Parquet européen les faits pouvant constituer une infraction de sa compétence.",u:["https://fr.wikipedia.org/wiki/Office_europ%C3%A9en_de_lutte_antifraude"],s:"Banque UE"},
{id:"ue2-216",t:"ue",q:"Quelle agence de l'Union a son siège à Valenciennes ?",o:["L'Agence de l'Union européenne pour les chemins de fer","L'Agence de l'Union européenne pour la sécurité aérienne","L'Agence européenne pour la sécurité maritime","L'Agence de l'Union européenne pour le programme spatial"],a:0,e:"L'agence de sécurité aérienne est à Cologne, celle de sécurité maritime à Lisbonne, celle du programme spatial à Prague.",u:["https://fr.wikipedia.org/wiki/Agence_de_l%27Union_europ%C3%A9enne_pour_les_chemins_de_fer"],s:"Banque UE"},
{id:"ue2-217",t:"ue",q:"Quel organisme de l'Union a son siège à Angers ?",o:["L'Office de l'Union européenne pour la propriété intellectuelle","L'Autorité européenne de sécurité des aliments","L'Office communautaire des variétés végétales","L'Agence européenne des produits chimiques"],a:2,e:"Il délivre les droits de propriété sur les variétés végétales. L'EUIPO est à Alicante, l'EFSA à Parme, l'ECHA à Helsinki.",u:["https://fr.wikipedia.org/wiki/Office_communautaire_des_vari%C3%A9t%C3%A9s_v%C3%A9g%C3%A9tales"],s:"Banque UE"},
{id:"ue2-218",t:"ue",q:"Où siège l'Agence de l'Union européenne pour la cybersécurité (ENISA) ?",o:["Tallinn","Bruxelles","Athènes","Rennes"],a:2,e:"Elle dispose aussi d'un bureau à Héraklion (Crète) ; en France, l'autorité nationale est l'ANSSI.",u:["https://fr.wikipedia.org/wiki/Agence_de_l%27Union_europ%C3%A9enne_pour_la_cybers%C3%A9curit%C3%A9"],s:"Banque UE"},
// --- Processus décisionnels ---
{id:"ue2-219",t:"ue",q:"Quel article du TFUE décrit la procédure législative ordinaire ?",o:["Article 49","Article 288","Article 294","Article 352"],a:2,e:"L'article 288 définit les actes (règlement, directive, décision...), l'article 352 est la clause de flexibilité.",u:["https://fr.wikipedia.org/wiki/Proc%C3%A9dure_l%C3%A9gislative_ordinaire"],s:"TFUE, art. 294"},
{id:"ue2-220",t:"ue",q:"Dans la procédure législative ordinaire, que se passe-t-il si le Conseil n'approuve pas tous les amendements du Parlement en deuxième lecture ?",o:["La proposition est adoptée d'office","La Cour de justice tranche","Le Conseil européen décide à l'unanimité","Un comité de conciliation est convoqué"],a:3,e:"Le comité dispose de six semaines pour établir un projet commun, ensuite soumis à une troisième lecture.",u:["https://fr.wikipedia.org/wiki/Proc%C3%A9dure_l%C3%A9gislative_ordinaire"],s:"TFUE, art. 294"},
{id:"ue2-221",t:"ue",q:"Comment est composé le comité de conciliation de la procédure législative ordinaire ?",o:["De membres du Conseil et d'un nombre égal de représentants du Parlement européen","De commissaires et de juges de la Cour de justice","Des présidents des trois institutions","De représentants des parlements nationaux"],a:0,e:"La Commission participe à ses travaux pour rapprocher les positions.",u:["https://fr.wikipedia.org/wiki/Proc%C3%A9dure_l%C3%A9gislative_ordinaire"],s:"TFUE, art. 294"},
{id:"ue2-222",t:"ue",q:"Qu'est-ce qu'un trilogue ?",o:["Un vote en trois lectures au Parlement européen","Une négociation informelle entre représentants du Parlement, du Conseil et de la Commission","Une réunion des trois présidences successives du Conseil","Une procédure contentieuse devant la Cour de justice"],a:1,e:"Les trilogues permettent d'aboutir à un accord dès la première lecture.",u:["https://fr.wikipedia.org/wiki/Trilogue"],s:"Banque UE"},
{id:"ue2-223",t:"ue",q:"À quel stade la plupart des actes sont-ils aujourd'hui adoptés en procédure législative ordinaire ?",o:["En deuxième lecture","En première lecture","Après conciliation","En troisième lecture"],a:1,e:"Grâce aux trilogues, l'immense majorité des textes est adoptée dès la première lecture ; la conciliation est devenue rare.",u:["https://fr.wikipedia.org/wiki/Proc%C3%A9dure_l%C3%A9gislative_ordinaire"],s:"Banque UE"},
{id:"ue2-224",t:"ue",q:"Dans la procédure législative spéciale de consultation, quel est le poids de l'avis du Parlement européen ?",o:["Il lie le Conseil","Il est facultatif","Il permet au Parlement de bloquer l'acte","Le Conseil doit le recueillir, mais n'est pas lié par son contenu"],a:3,e:"L'absence de consultation entraîne l'annulation de l'acte (arrêt Isoglucose, 1980). C'est la procédure applicable à la fiscalité.",u:["https://fr.wikipedia.org/wiki/Proc%C3%A9dure_l%C3%A9gislative_ordinaire"],s:"Banque UE"},
{id:"ue2-225",t:"ue",q:"Que permet une clause « passerelle » ?",o:["Passer de l'unanimité à la majorité qualifiée, ou d'une procédure spéciale à la procédure ordinaire, sans révision formelle des traités","Adhérer à l'Union sans négociation d'adhésion","Quitter la zone euro sans quitter l'Union","Créer une nouvelle institution sans ratification"],a:0,e:"La passerelle générale (art. 48, paragraphe 7, TUE) requiert l'unanimité du Conseil européen et l'approbation du Parlement.",u:["https://fr.wikipedia.org/wiki/Trait%C3%A9_sur_l%27Union_europ%C3%A9enne"],s:"TUE, art. 48"},
{id:"ue2-226",t:"ue",q:"Dans la clause passerelle générale de l'article 48 TUE, de quel délai chaque parlement national dispose-t-il pour s'y opposer ?",o:["8 semaines","3 mois","6 mois","1 an"],a:2,e:"L'opposition d'un seul parlement national suffit à empêcher l'adoption de la décision.",u:["https://fr.wikipedia.org/wiki/Trait%C3%A9_sur_l%27Union_europ%C3%A9enne"],s:"TUE, art. 48"},
{id:"ue2-227",t:"ue",q:"Selon la procédure de révision ordinaire des traités, comment les modifications entrent-elles en vigueur ?",o:["Après un vote à la majorité qualifiée du Conseil","Après un vote du seul Parlement européen","Après ratification par tous les États membres selon leurs règles constitutionnelles","Après approbation de la Commission"],a:2,e:"Art. 48 TUE : convention, puis conférence des représentants des gouvernements, puis ratifications.",u:["https://fr.wikipedia.org/wiki/Trait%C3%A9_sur_l%27Union_europ%C3%A9enne"],s:"TUE, art. 48"},
{id:"ue2-228",t:"ue",q:"Combien d'États membres faut-il au minimum pour engager une coopération renforcée ?",o:["3","5","9","14"],a:2,e:"Art. 20 TUE ; elle n'est autorisée qu'en dernier ressort.",u:["https://fr.wikipedia.org/wiki/Coop%C3%A9ration_renforc%C3%A9e"],s:"TUE, art. 20"},
{id:"ue2-229",t:"ue",q:"Qui autorise une coopération renforcée en dehors de la PESC ?",o:["Le Conseil européen, à l'unanimité","Les seuls États participants","Le Conseil, sur proposition de la Commission et après approbation du Parlement européen","La Cour de justice de l'Union"],a:2,e:"Art. 329 TFUE ; en PESC, le Conseil statue à l'unanimité.",u:["https://fr.wikipedia.org/wiki/Coop%C3%A9ration_renforc%C3%A9e"],s:"TFUE, art. 329"},
{id:"ue2-230",t:"ue",q:"Dans quel domaine la première coopération renforcée a-t-elle été mise en œuvre, en 2010 ?",o:["La taxe sur les transactions financières","La loi applicable au divorce","Le brevet à effet unitaire","Le Parquet européen"],a:1,e:"Règlement « Rome III ». Suivent le brevet unitaire (2012), les régimes matrimoniaux (2016) et le Parquet européen (2017).",u:["https://fr.wikipedia.org/wiki/Coop%C3%A9ration_renforc%C3%A9e"],s:"Banque UE"},
{id:"ue2-231",t:"ue",q:"Quel mécanisme du TUE, lancé en décembre 2017, permet une coopération approfondie en matière de défense ?",o:["La clause passerelle","La coopération politique européenne","Le Partenariat oriental","La coopération structurée permanente"],a:3,e:"Art. 42, paragraphe 6, et art. 46 TUE ; la quasi-totalité des États y participent.",u:["https://fr.wikipedia.org/wiki/Coop%C3%A9ration_structur%C3%A9e_permanente"],s:"TUE, art. 46"},
{id:"ue2-232",t:"ue",q:"Selon le principe d'attribution, de quelles compétences l'Union dispose-t-elle ?",o:["Uniquement de celles que les États membres lui ont attribuées dans les traités","De toutes celles que les États n'exercent pas","De toutes les compétences économiques","De celles que lui reconnaît la Cour de justice"],a:0,e:"Art. 5, paragraphe 2, TUE : toute compétence non attribuée appartient aux États membres.",u:["https://fr.wikipedia.org/wiki/Principe_d%27attribution"],s:"TUE, art. 5"},
{id:"ue2-233",t:"ue",q:"Quel article du TFUE, dit « clause de flexibilité », permet d'agir à l'unanimité sans base juridique spécifique pour atteindre un objectif des traités ?",o:["Article 48","Article 222","Article 294","Article 352"],a:3,e:"Le Conseil statue à l'unanimité, sur proposition de la Commission et après approbation du Parlement européen.",s:"TFUE, art. 352"},
{id:"ue2-234",t:"ue",q:"Dans la procédure de l'article 7 TUE, qui constate l'existence d'une violation grave et persistante des valeurs de l'Union par un État ?",o:["Le Parlement européen seul","Le Conseil européen, à l'unanimité, sans prendre en compte le vote de l'État concerné","La Cour de justice de l'Union","La Commission seule"],a:1,e:"Après approbation du Parlement ; le Conseil peut ensuite suspendre certains droits, dont le droit de vote, à la majorité qualifiée.",u:["https://fr.wikipedia.org/wiki/Article_7_du_trait%C3%A9_sur_l%27Union_europ%C3%A9enne"],s:"TUE, art. 7"},
// --- Rôle des parlements nationaux ---
{id:"ue2-235",t:"ue",q:"De quel délai les parlements nationaux disposent-ils pour adresser un avis motivé sur la conformité d'un projet d'acte législatif au principe de subsidiarité ?",o:["4 semaines","8 semaines","3 mois","6 mois"],a:1,e:"À compter de la transmission du projet (protocole n° 2 sur la subsidiarité et la proportionnalité).",u:["https://fr.wikipedia.org/wiki/Principe_de_subsidiarit%C3%A9"],s:"Protocole n° 2"},
{id:"ue2-236",t:"ue",q:"Combien de voix chaque parlement national dispose-t-il dans le contrôle de la subsidiarité ?",o:["Deux voix, partagées entre les deux chambres en cas de parlement bicaméral","Une voix par parlementaire","Une seule voix","Un nombre de voix proportionnel à la population"],a:0,e:"En France, l'Assemblée nationale et le Sénat disposent chacun d'une voix.",u:["https://fr.wikipedia.org/wiki/Principe_de_subsidiarit%C3%A9"],s:"Protocole n° 2"},
{id:"ue2-237",t:"ue",q:"Quel seuil déclenche le « carton jaune » obligeant à réexaminer un projet d'acte législatif ?",o:["La majorité simple des voix","Les deux tiers des voix","L'unanimité des parlements","Un tiers des voix attribuées aux parlements nationaux"],a:3,e:"Seuil abaissé à un quart pour la coopération judiciaire pénale et policière ; la Commission peut maintenir, modifier ou retirer son projet.",u:["https://fr.wikipedia.org/wiki/Principe_de_subsidiarit%C3%A9"],s:"Protocole n° 2"},
{id:"ue2-238",t:"ue",q:"Quel seuil déclenche le « carton orange » dans la procédure législative ordinaire ?",o:["Un quart des voix","Un tiers des voix","La majorité simple des voix attribuées aux parlements nationaux","Les trois quarts des voix"],a:2,e:"Si la Commission maintient sa proposition, le Parlement ou le Conseil peut y mettre fin.",u:["https://fr.wikipedia.org/wiki/Principe_de_subsidiarit%C3%A9"],s:"Protocole n° 2"},
{id:"ue2-239",t:"ue",q:"Sur quel projet le premier « carton jaune » des parlements nationaux a-t-il été déclenché, en 2012 ?",o:["Le règlement « Monti II » sur l'exercice du droit de grève","La directive sur les travailleurs détachés","Le règlement instituant le Parquet européen","Le règlement général sur la protection des données"],a:0,e:"La Commission a retiré sa proposition. D'autres ont suivi, notamment sur le Parquet européen (2013) et les travailleurs détachés (2016).",u:["https://fr.wikipedia.org/wiki/Principe_de_subsidiarit%C3%A9"],s:"Banque UE"},
{id:"ue2-240",t:"ue",q:"Selon l'article 88-6 de la Constitution, qui peut émettre un avis motivé sur la conformité d'un projet d'acte législatif européen au principe de subsidiarité ?",o:["Le Conseil d'État","Le Conseil constitutionnel","L'Assemblée nationale ou le Sénat","Le Président de la République"],a:2,e:"L'avis est adressé par le président de l'assemblée aux présidents du Parlement européen, du Conseil et de la Commission ; le Gouvernement en est informé.",u:["https://fr.wikipedia.org/wiki/Constitution_fran%C3%A7aise_du_4_octobre_1958"],s:"Constitution, art. 88-6"},
{id:"ue2-241",t:"ue",q:"Selon l'article 88-6 de la Constitution, à la demande de qui le recours devant la Cour de justice de l'Union pour violation du principe de subsidiarité est-il de droit ?",o:["De 30 députés ou de 30 sénateurs","De 60 députés ou de 60 sénateurs","De 185 parlementaires","Du dixième des électeurs inscrits"],a:1,e:"Le recours est transmis à la Cour par le Gouvernement.",u:["https://fr.wikipedia.org/wiki/Constitution_fran%C3%A7aise_du_4_octobre_1958"],s:"Constitution, art. 88-6"},
{id:"ue2-242",t:"ue",q:"Selon l'article 88-4 de la Constitution, sur quoi les assemblées peuvent-elles adopter des résolutions européennes ?",o:["Sur les arrêts de la Cour de justice de l'Union","Sur la nomination des commissaires","Sur les décisions de politique monétaire de la BCE","Sur les projets d'actes législatifs européens et autres projets ou documents de l'Union"],a:3,e:"Le Gouvernement leur soumet ces projets dès leur transmission au Conseil de l'UE.",u:["https://fr.wikipedia.org/wiki/Constitution_fran%C3%A7aise_du_4_octobre_1958"],s:"Constitution, art. 88-4"},
{id:"ue2-243",t:"ue",q:"Quel organe l'article 88-4 de la Constitution institue-t-il au sein de chaque assemblée ?",o:["Une délégation aux droits des femmes","Une commission d'enquête permanente","Une commission chargée des affaires européennes","Un comité de conciliation"],a:2,e:"Depuis la révision de 2008 ; elles ont remplacé les délégations pour l'Union européenne, créées en 1979 (alors « pour les Communautés européennes »).",u:["https://fr.wikipedia.org/wiki/Constitution_fran%C3%A7aise_du_4_octobre_1958"],s:"Constitution, art. 88-4"},
{id:"ue2-244",t:"ue",q:"Selon l'article 88-7 de la Constitution, comment le Parlement français peut-il s'opposer au recours à une clause passerelle ?",o:["Par un référendum","Par une motion adoptée en termes identiques par l'Assemblée nationale et le Sénat","Par une décision du Conseil constitutionnel","Par un décret du Premier ministre"],a:1,e:"Cela permet d'exercer le droit d'opposition reconnu à chaque parlement national par l'article 48 TUE.",u:["https://fr.wikipedia.org/wiki/Constitution_fran%C3%A7aise_du_4_octobre_1958"],s:"Constitution, art. 88-7"},
{id:"ue2-245",t:"ue",q:"Selon l'article 88-3 de la Constitution, quel droit est reconnu aux citoyens de l'Union résidant en France ?",o:["Le droit de vote aux élections législatives","Le droit de vote à l'élection présidentielle","Le droit d'exercer les fonctions de maire","Le droit de vote et d'éligibilité aux élections municipales"],a:3,e:"Ils ne peuvent toutefois être ni maire ni adjoint, ni participer à l'élection des sénateurs.",u:["https://fr.wikipedia.org/wiki/Constitution_fran%C3%A7aise_du_4_octobre_1958"],s:"Constitution, art. 88-3"},
{id:"ue2-246",t:"ue",q:"Quel article de la Constitution affirme que la République participe à l'Union européenne ?",o:["Article 34","Article 55","Article 88-1","Article 89"],a:2,e:"L'Union y est définie comme constituée d'États qui ont choisi librement d'exercer en commun certaines de leurs compétences.",u:["https://fr.wikipedia.org/wiki/Constitution_fran%C3%A7aise_du_4_octobre_1958"],s:"Constitution, art. 88-1"},
// --- Symboles, langues et citoyenneté ---
{id:"ue2-247",t:"ue",q:"Quelle est la devise de l'Union européenne ?",o:["« Unie dans la diversité »","« Liberté, égalité, fraternité »","« L'union fait la force »","« Paix, prospérité, progrès »"],a:0,e:"En latin « In varietate concordia », adoptée en 2000. « L'union fait la force » est la devise de la Belgique.",u:["https://european-union.europa.eu/principles-countries-history/symbols_fr"],s:"Banque UE"},
{id:"ue2-248",t:"ue",q:"Quel jour l'Union européenne célèbre-t-elle la Journée de l'Europe ?",o:["Le 5 mai","Le 9 mai","Le 25 mars","Le 1er novembre"],a:1,e:"Anniversaire de la déclaration Schuman ; le Conseil de l'Europe célèbre, lui, sa journée le 5 mai (date de sa création en 1949).",u:["https://fr.wikipedia.org/wiki/Journ%C3%A9e_de_l%27Europe_(Union_europ%C3%A9enne)"],s:"Banque UE"},
{id:"ue2-249",t:"ue",q:"Quelle organisation a la première adopté, en 1955, le drapeau aux douze étoiles d'or sur fond bleu ?",o:["La CECA","La CEE","Le Conseil de l'Europe","L'OTAN"],a:2,e:"Les Communautés européennes l'ont adopté en 1985 ; le nombre d'étoiles est invariable.",u:["https://fr.wikipedia.org/wiki/Drapeau_europ%C3%A9en"],s:"Banque UE"},
{id:"ue2-250",t:"ue",q:"L'hymne européen comporte-t-il des paroles officielles ?",o:["Oui, en latin","Oui, le poème de Schiller en allemand","Oui, dans les 24 langues officielles","Non, il est uniquement instrumental"],a:3,e:"Le prélude de l'« Ode à la joie » de Beethoven, dans un arrangement d'Herbert von Karajan, est utilisé sans paroles.",u:["https://european-union.europa.eu/principles-countries-history/symbols_fr"],s:"Banque UE"},
{id:"ue2-251",t:"ue",q:"Combien de langues officielles l'Union européenne a-t-elle comptées à partir de l'adhésion de la Croatie, en 2013 ?",o:["12","23","24","28"],a:2,e:"Le croate a porté leur nombre de 23 à 24. Le régime linguistique est fixé par le Conseil à l'unanimité (art. 342 TFUE, règlement n° 1/1958).",u:["https://fr.wikipedia.org/wiki/Langues_officielles_de_l%27Union_europ%C3%A9enne"],s:"Banque UE"},
{id:"ue2-252",t:"ue",q:"La citoyenneté de l'Union :",o:["S'ajoute à la citoyenneté nationale et ne la remplace pas","Remplace la nationalité des États membres","S'acquiert par une demande à la Commission","Est réservée aux résidents de la zone euro"],a:0,e:"Art. 20 TFUE : est citoyen de l'Union toute personne ayant la nationalité d'un État membre.",u:["https://fr.wikipedia.org/wiki/Citoyennet%C3%A9_de_l%27Union_europ%C3%A9enne"],s:"TFUE, art. 20"},
{id:"ue2-253",t:"ue",q:"Dans un pays tiers où la France n'est pas représentée, quel droit la citoyenneté de l'Union confère-t-elle à un Français ?",o:["Une protection assurée par les Nations unies","Aucune protection particulière","Une protection assurée par la seule Commission européenne","La protection consulaire de tout autre État membre, comme ses propres nationaux"],a:3,e:"Art. 20 et 23 TFUE.",u:["https://fr.wikipedia.org/wiki/Citoyennet%C3%A9_de_l%27Union_europ%C3%A9enne"],s:"TFUE, art. 23"},
{id:"ue2-254",t:"ue",q:"Quelle ville française sera capitale européenne de la culture en 2028 ?",o:["Rouen","Clermont-Ferrand","Bourges","Montpellier"],a:2,e:"Choisie en décembre 2023 face à Rouen, Clermont-Ferrand et Montpellier ; Marseille l'avait été en 2013.",u:["https://fr.wikipedia.org/wiki/Capitale_europ%C3%A9enne_de_la_culture"],s:"Banque UE"},
{id:"ue2-255",t:"ue",q:"Quel prix l'Union européenne a-t-elle reçu en 2012 ?",o:["Le prix Sakharov","Le prix Nobel de la paix","Le prix Charlemagne","Le prix Princesse des Asturies"],a:1,e:"Pour sa contribution, pendant plus de soixante ans, à la paix, à la réconciliation, à la démocratie et aux droits de l'homme en Europe.",s:"Banque UE"},
// --- Actualité : présidences du Conseil de l'UE 2026-2028 (vérifié le 17 oct. 2026) ---
{id:"act27-10",t:"ue",q:"Quel État membre a présidé le Conseil de l'Union européenne au premier semestre 2026 ?",o:["Le Danemark","Chypre","L'Irlande","Malte"],a:1,e:"Chypre a succédé au Danemark le 1er janvier 2026 et a passé le relais à l'Irlande le 1er juillet 2026.",x:"C'était la deuxième présidence chypriote, après celle du second semestre 2012 ; elle clôturait le trio formé avec la Pologne et le Danemark.",u:["https://fr.wikipedia.org/wiki/Pr%C3%A9sidence_chypriote_du_Conseil_de_l'Union_europ%C3%A9enne_en_2026","https://fr.wikipedia.org/wiki/Pr%C3%A9sidence_du_Conseil_de_l'Union_europ%C3%A9enne"],s:"Calendrier des présidences du Conseil",act:1},
{id:"act27-11",t:"ue",q:"Quel État membre présidera le Conseil de l'Union européenne au second semestre 2027 ?",o:["La Lituanie","La Grèce","L'Italie","La Lettonie"],a:1,e:"La Grèce succédera à la Lituanie le 1er juillet 2027 et clôturera le trio formé avec l'Irlande et la Lituanie.",x:"Ce sera sa sixième présidence ; la précédente remonte au premier semestre 2014.",u:["https://fr.wikipedia.org/wiki/Pr%C3%A9sidence_du_Conseil_de_l'Union_europ%C3%A9enne"],s:"Calendrier des présidences du Conseil",act:1},
{id:"act27-12",t:"ue",q:"Quel État membre ouvrira, au premier semestre 2028, le trio de présidences du Conseil de l'UE qui suivra celui de l'Irlande, de la Lituanie et de la Grèce ?",o:["L'Italie","La Lettonie","Le Luxembourg","La France"],a:0,e:"L'Italie (1er semestre 2028) sera suivie de la Lettonie (2nd semestre 2028), puis du Luxembourg (1er semestre 2029).",x:"L'ordre de rotation est fixé à l'avance par une décision du Conseil, la dernière datant de 2016 ; chaque trio adopte un programme commun sur dix-huit mois.",u:["https://fr.wikipedia.org/wiki/Pr%C3%A9sidence_du_Conseil_de_l'Union_europ%C3%A9enne"],s:"Calendrier des présidences du Conseil",act:1}
);
